// Random line from a character/trigger pool.
// A flat selection uses the actual proportions within the chosen trigger pool.
function getDialogueLine(character, trigger, options = {}) {
  const {
    allowMovieHomages = true,
    avoidRepeat = null
  } = options;

  const pool = BLOCK_HUNTER_DIALOGUES?.[character]?.[trigger] || [];
  if (!pool.length) return null;

  let candidates = allowMovieHomages
    ? pool
    : pool.filter(line => line.type === "original");

  if (avoidRepeat && candidates.length > 1) {
    candidates = candidates.filter(line => line.text !== avoidRepeat);
  }

  if (!candidates.length) return null;
  return candidates[Math.floor(Math.random() * candidates.length)];
}

// Optional weighted selector.
// Requests a 30% movie-homage selection chance where both types are available.
function getDialogueLineWeighted(character, trigger, movieChance = 0.30) {
  const pool = BLOCK_HUNTER_DIALOGUES?.[character]?.[trigger] || [];
  if (!pool.length) return null;

  const movie = pool.filter(line => line.type === "movie_homage");
  const original = pool.filter(line => line.type === "original");

  const preferMovie = Math.random() < movieChance;
  const chosenPool =
    preferMovie && movie.length ? movie :
    original.length ? original :
    movie;

  return chosenPool[Math.floor(Math.random() * chosenPool.length)];
}

// Example:
// const line = getDialogueLineWeighted("BOSS", "boss_phase_2");
// if (line) showSpeechBubble(line.text);

if (typeof module !== "undefined" && module.exports) {
  module.exports = {
    BLOCK_HUNTER_DIALOGUES,
    getDialogueLine,
    getDialogueLineWeighted
  };
}

'use strict';
// Select a category first for 30% homages within the approved active bank.
const dialogue={time:0,active:null,queue:[],gap:0,last:new Map(),cooldown:new Map()};
function clearActiveDialogue(){if(typeof gameSound!=='undefined')gameSound.stopDialogue();dialogue.active=null;dialogueCaption('');}
function resetDialogues(){dialogue.time=0;clearActiveDialogue();dialogue.queue=[];dialogue.gap=0;dialogue.cooldown.clear();}
function dialogueCaption(text){const node=document.getElementById('dialogueText');if(node)node.textContent=text;}
function dialogueCharacter(speaker){return speaker==='hero'?'HERO':speaker==='princess'?'PRINCESS':speaker.type.toUpperCase();}
function dialogueValid(item){
 if(item.scene!==currentScene)return false;
 if(item.speaker==='hero')return hero.hp>0;
 if(item.speaker==='princess')return currentScene==='castle';
 return enemies.includes(item.speaker)&&(item.speaker.hp>0||item.trigger==='death');
}
function chooseDialogue(character,trigger){
 let pool=BLOCK_HUNTER_DIALOGUES[character==='BANDIT'?'BRUTE':character]?.[trigger];
 // Hero dialogue is audio-only: do not reserve a turn for a missing recording.
 if(character==='HERO'&&pool&&typeof HERO_VOICES!=='undefined')pool=pool.filter(line=>HERO_VOICES[line.text]);
 if(!pool?.length)return null;
 const key=character+':'+trigger,previous=dialogue.last.get(key);
 const preferMovie=Math.random()<.30;
 let candidates=pool.filter(p=>p.type===(preferMovie?'movie_homage':'original'));
 if(!candidates.length)candidates=pool;
 // Avoid repetition within the selected category without skewing its weight.
 const alternatives=candidates.filter(p=>p.text!==previous);
 if(alternatives.length)candidates=alternatives;
 const line=candidates[Math.floor(Math.random()*candidates.length)];
 dialogue.last.set(key,line.text);return line;
}
function sayDialogue(speaker,trigger,priority=1,force=false){if(campaignLevel===8&&castle8.voice?.active)return false;
 const character=dialogueCharacter(speaker),key=character+':'+trigger;
 const item={speaker,trigger,character,priority,scene:currentScene,created:dialogue.time};
 if(!dialogueValid(item))return false;
 if(!force&&(dialogue.cooldown.get(key)||0)>dialogue.time)return false;
 if(dialogue.queue.some(p=>p.speaker===speaker&&p.trigger===trigger)||dialogue.active?.speaker===speaker&&dialogue.active.trigger===trigger)return false;
 if(priority===1&&(dialogue.active||dialogue.queue.length))return false;
 if(dialogue.queue.length>=4){const low=dialogue.queue.findIndex(p=>p.priority<priority);if(low<0)return false;dialogue.queue.splice(low,1);}
 const line=chooseDialogue(character,trigger);if(!line)return false;
 Object.assign(item,{text:line.text,type:line.type,duration:Math.max(2.2,Math.min(4.2,1.1+line.text.length/16)),remaining:0});
 dialogue.cooldown.set(key,dialogue.time+(priority===1?9:12));
 dialogue.queue.push(item);return true;
}
// Tower guards stay quiet on sight; an actual arrow release can trigger their attack line.
function dialogueArcherShot(e){
 if(e.type!=='archer'||e.hp<=0||hero.hp<=0)return false;
 const left=camera.x??Math.max(0,hero.x-W*.42);
 if(e.x<left||e.x>left+W)return false;
 return sayDialogue(e,'attack');
}
function dialogueCombat(e){
 if(e.silent)return;
 if(!e._dialogueCombat){e._dialogueCombat=true;sayDialogue('hero','combat_start',2);sayDialogue(e,'combat_start',2);}
 else if(e.type!=='archer')sayDialogue(e,'attack');
}
function dialogueEnemyHit(e){
 if(e.silent)return;
 if(e.hp===0){
  // Discard stale combat banter; last words may come from the dying enemy.
  clearActiveDialogue();dialogue.queue=[];dialogue.gap=0;
  sayDialogue(e,'death',5,true);sayDialogue('hero','kill',4,true);return;
 }
 if(e.type==='boss'){
  if(e.hp/e.maxHP<=.25&&!e._dialogueLow){e._dialogueLow=true;sayDialogue(e,'low_health',4);}
  else if(e.hp/e.maxHP<=.5&&!e._dialoguePhase){e._dialoguePhase=true;sayDialogue(e,'boss_phase_2',3);}
 }else sayDialogue(e,'take_damage');
}
function updateDialogues(dt){if(campaignLevel===8&&castle8.voice?.active)return;if(campaignLevel===7&&!dungeon.gear)return;
 dialogue.time+=dt;
 if(hero.hp<=0){clearActiveDialogue();dialogue.queue=[];return;}
 dialogue.gap=Math.max(0,dialogue.gap-dt);
 if(dialogue.active){dialogue.active.remaining-=dt;if(dialogue.active.remaining<=0||!dialogueValid(dialogue.active)){clearActiveDialogue();dialogue.gap=.35;}}
 // Encounter events fire once per enemy lifetime, including room revisits.
 for(const e of enemies){if(e.hidden||e.emerging>0||e.hp<=0||e.silent)continue;
  if(!e._dialogueSeen&&Math.abs(e.x-hero.x)<460&&Math.abs(e.y-hero.y)<240){e._dialogueSeen=true;sayDialogue('hero','enemy_spotted',2);sayDialogue(e,'enemy_spotted',2);}
  if(e.type==='archer'&&Math.abs(e.x-hero.x)<110&&Math.abs(e.y-hero.y)<55&&!e._dialogueClose){e._dialogueClose=true;sayDialogue(e,'player_close',3);}
 }
 dialogue.queue=dialogue.queue.filter(p=>dialogueValid(p)&&dialogue.time-p.created<(p.priority>=2?12:3));
 if(!dialogue.active&&dialogue.gap===0&&dialogue.queue.length){
  // Higher-priority events supersede routine chatter, stable for equal priority.
  dialogue.queue.sort((a,b)=>b.priority-a.priority);dialogue.active=dialogue.queue.shift();dialogue.active.remaining=dialogue.active.duration;
  dialogueCaption(dialogue.active.character==='HERO'?'':dialogue.active.character+': '+dialogue.active.text);
  // Audio starts when the queued line becomes active, independently of bubbles.
  if(typeof gameSound!=='undefined'){
   const duration=gameSound.speak(dialogue.active.character,dialogue.active.text);
   dialogue.active.remaining=dialogue.active.duration=Math.max(dialogue.active.duration,duration+.3);
  }
 }
}
function dialogueSpeakerPoint(speaker){
 if(speaker==='hero')return {x:hero.x,y:hero.y-heroBodyHeight()};
 if(speaker==='princess'){const frame=princessFrame(),s=princessArt.idle?.[0]?120/princessArt.idle[0].height:0;return{x:reunion.x,y:FLOOR-(frame?frame.height*s:120)};}
 // Keep the same standing-height anchor during attacks, hits and death poses.
 return {x:speaker.x,y:speaker.y-speaker.height};
}
function speechLayout(text,point,w,h,measure){
 const font=Math.max(14,Math.min(18,w/46)),lineHeight=font*1.25,maxWidth=Math.max(60,Math.min(260,w-24));
 const lines=[];let line='';for(const word of text.split(/\s+/)){const candidate=line?line+' '+word:word;if(line&&measure(candidate)>maxWidth-24){lines.push(line);line=word;}else line=candidate;}if(line)lines.push(line);
 const width=Math.min(maxWidth,Math.max(70,...lines.map(measure))+24),height=lines.length*lineHeight+20;
 const x=Math.max(8,Math.min(w-width-8,point.x-width/2)),y=Math.max(8,Math.min(h-height-18,point.y-height-19));
 return {font,lineHeight,lines,width,height,x,y,tailX:Math.max(x+14,Math.min(x+width-14,point.x)),tipX:Math.max(8,Math.min(w-8,point.x)),tipY:Math.max(y+height+6,Math.min(h-4,point.y-5))};
}
function drawDialogue(w,h,paint=ctx,active=dialogue.active){
 const ctx=paint;
 const a=active;if(!a||a.character==='HERO'||!dialogueValid(a))return;
 const world=dialogueSpeakerPoint(a.speaker),scale=w/W,point={x:(world.x-(camera.x||0))*scale,y:(world.y-camera.y)*scale};
 if(point.y<-20||point.y>h+20||point.x<0||point.x>w)return;
 ctx.save();const font=Math.max(14,Math.min(18,w/46));ctx.font='700 '+font+'px "Comic Sans MS", "Trebuchet MS", sans-serif';
 const b=speechLayout(a.text,point,w,h,t=>ctx.measureText(t).width),r=12;
 ctx.globalAlpha=Math.min(1,a.remaining/.25);ctx.fillStyle='#fff9e9';ctx.strokeStyle='#231911';ctx.lineWidth=2;
 ctx.shadowColor='#0008';ctx.shadowBlur=3;ctx.shadowOffsetY=3;
 ctx.beginPath();ctx.moveTo(b.x+r,b.y);ctx.lineTo(b.x+b.width-r,b.y);ctx.quadraticCurveTo(b.x+b.width,b.y,b.x+b.width,b.y+r);ctx.lineTo(b.x+b.width,b.y+b.height-r);ctx.quadraticCurveTo(b.x+b.width,b.y+b.height,b.x+b.width-r,b.y+b.height);
 ctx.lineTo(b.tailX+7,b.y+b.height);ctx.lineTo(b.tipX,b.tipY);ctx.lineTo(b.tailX-7,b.y+b.height);ctx.lineTo(b.x+r,b.y+b.height);ctx.quadraticCurveTo(b.x,b.y+b.height,b.x,b.y+b.height-r);ctx.lineTo(b.x,b.y+r);ctx.quadraticCurveTo(b.x,b.y,b.x+r,b.y);ctx.closePath();ctx.fill();ctx.stroke();
 ctx.shadowBlur=0;ctx.shadowOffsetY=0;ctx.fillStyle='#201611';ctx.textAlign='center';ctx.textBaseline='top';b.lines.forEach((line,i)=>ctx.fillText(line,b.x+b.width/2,b.y+10+i*b.lineHeight));ctx.restore();
}

