function updateLevelHUD(){if(campaignLevel===8){updateCastle8HUD();return;}if(campaignLevel===7){updateDungeonHUD();return;}if(campaignLevel===6){updateCityHUD();return;}if(campaignLevel===5){updateSawmillHUD();return;}const select=document.getElementById("campaignSelect");if(select)select.value=String(campaignLevel);if(campaign&&campaignLevel===4){updateForestHUD();return;}updateEnergy();if(!campaign)return;level.index=Math.max(0,SECTIONS.findLastIndex(s=>hero.x>=s.x));document.getElementById('wealthValue').textContent=wealth;document.getElementById('armorValue').textContent=armor+' / 4';document.getElementById('ammoValue').textContent=(level.gun?level.ammo:0)+' / 0';document.getElementById('armorMeter').value=armor;document.querySelector('.levelBadge')?.setAttribute('aria-label','Level '+campaignLevel);const badge=document.querySelector('.levelBadge');if(badge)badge.textContent=campaignLevel;document.getElementById('bridgeLevel').hidden=false;document.getElementById('bridgeLevel').textContent=campaignLevel===2?'Valley Ruins':level.done?'Continue to Old Bridge':'Old Bridge';document.getElementById('newLevel').textContent=level.done&&campaignLevel===3?'Continue to Black Forest':level.done&&campaignLevel===2?'Continue to River':level.done&&campaignLevel===1?'Continue to Old Bridge':'New game';document.getElementById('levelProgress').textContent=(campaignLevel===3?'RIVER · ':campaignLevel===2?'OLD BRIDGE · ':'')+(level.index+1)+' / 6 · '+SECTIONS[level.index].name;for(const k of ['sword','guard','shoot'])document.querySelector('[data-key="'+k+'"]')?.setAttribute('aria-disabled',String(k==='shoot'||!hasSword));document.getElementById('retryLevel').textContent=level.done?'Play again':level.checkpoint?'From checkpoint':'Restart level';}
