function strikeCrates(){if(!campaign)return;for(const c of crates){if(c.broken||isLootLocked(c))continue;if(Math.abs(hero.x-c.x)<143&&(c.x-hero.x)*hero.face>=-12&&hero.y+8>=c.y-68&&hero.y-100<c.y){c.broken=true;pickups.push({id:c.id,kind:c.kind,x:c.x,y:c.y,active:true,taken:false});clash(c.x,c.y-25);}}}
