function valleyBlock(previousX){if(campaignLevel===8)blockCastle8(previousX);if(campaignLevel===7)blockDungeon(previousX);if(!campaign)return;for(const p of platforms){if(((campaignLevel===7||campaignLevel===8)&&p.stepSolid)||p.ceiling||p.loose||p.bridge||(p.wood&&!(campaignLevel===5&&p.stepSolid))||p.fallen||(campaignLevel>=2?!p.solid:p.x>6500||p.y<300))continue;if(hero.x+19>p.x&&hero.x-19<p.x+p.w&&hero.y>p.y+1&&hero.y<p.y+100){if(hero.ground&&hero.y-p.y<=24){hero.y=p.y;}else{hero.x=previousX<p.x+p.w/2?p.x-19:p.x+p.w+19;if(hero.ground)hero.vx=0;}}}const obstacles=[...crates.filter(c=>!c.broken).map(c=>({x:c.x-24,w:48,bottom:c.y,top:c.y-68})),...platforms.filter(p=>p.ceiling).map(p=>({...p,top:p.y})),...(campaignLevel===1&&enemies.some(e=>e.type==='brute'&&e.hp>0)?[{x:11980,w:35,top:0,bottom:366}]:[])];for(const o of obstacles)if(hero.x+19>o.x&&hero.x-19<o.x+o.w&&hero.y>o.top&&hero.y-(o.rollOnly&&hero.state!=='roll'?120:heroBodyHeight())<o.bottom){hero.x=previousX<o.x+o.w/2?o.x-19:o.x+o.w+19;hero.vx=0;}}
