function riverBackdropBlend(x){const anchors=[{x:0,key:'river'},{x:2100,key:'river'},{x:3500,key:'mill-exterior'},{x:5000,key:'storehouse'},{x:6500,key:'sluice-yard'},{x:8100,key:'forest'}];let i=0;while(i<anchors.length-2&&x>anchors[i+1].x)i++;const a=anchors[i],b=anchors[i+1],t=Math.max(0,Math.min(1,(x-a.x)/(b.x-a.x)));return {a,b,t:t*t*(3-2*t)};}
function drawRiverBackdrop(vw,vh){const x=camera.x===null?hero.x:camera.x+W*.42,blend=riverBackdropBlend(x);for(const [key,alpha] of [[blend.a.key,1],[blend.b.key,blend.t]]){const im=riverArt[key];if(!im)continue;const scale=Math.max(vw/im.width,vh/im.height)*1.10,w=im.width*scale,h=im.height*scale;const pan=Math.sin(x/2400)*vw*.035;ctx.save();ctx.globalAlpha=alpha;ctx.drawImage(im,(vw-w)/2-pan,(vh-h)/2,w,h);ctx.restore();}}

