function forestReady(){
 document.getElementById('campaignBar').hidden=false;document.querySelector('.sceneBar')?.classList.add('labHidden');
 for(const id of ['riverLevel','bridgeLevel','labMode','playLevel'])document.getElementById(id).hidden=true;
 const menu=document.getElementById('campaignSelect');if(menu)menu.hidden=!!window.FOREST_STANDALONE;
 const n=document.getElementById('newLevel');n.hidden=false;n.onclick=()=>level.done&&!window.FOREST_STANDALONE?startSawmill({wealth,armor}):startForest({wealth:0,armor:0});
 document.getElementById('retryLevel').onclick=retryForest;updateForestHUD();
}
function updateForestHUD(){const select=document.getElementById("campaignSelect");if(select)select.value="4";
 updateEnergy();level.index=Math.max(0,FOREST_SECTIONS.findLastIndex(s=>hero.x>=s.x));
 document.getElementById('wealthValue').textContent=wealth;document.getElementById('armorValue').textContent=armor+' / 4';document.getElementById('ammoValue').textContent='0 / 0';document.getElementById('armorMeter').value=armor;
 const badge=document.querySelector('.levelBadge');if(badge){badge.textContent=4;badge.setAttribute('aria-label','Level 4');}
 document.getElementById('levelProgress').textContent='BLACK FOREST · '+(level.index+1)+' / 6 · '+FOREST_SECTIONS[level.index].name;
 document.getElementById('newLevel').textContent=level.done?(window.FOREST_STANDALONE?'Play again':'Next: Sawmill'):'Restart forest';
 document.getElementById('retryLevel').textContent=level.done?'Play again':forestCP?'From checkpoint':'Restart level';
 document.querySelector('[data-key="shoot"]')?.setAttribute('aria-disabled','true');
 for(const k of ['sword','guard'])document.querySelector('[data-key="'+k+'"]')?.setAttribute('aria-disabled','false');
}
function captureForestState(){return {time:forestTime,cp:forestCP,callAt:forestCallAt,bats:JSON.parse(JSON.stringify(forestBats))};}
function restoreForestState(s){if(!s)return;forestTime=s.time||0;forestCP=s.cp||0;forestCallAt=s.callAt||forestTime+5;forestBats=JSON.parse(JSON.stringify(s.bats||forestBats));}
function persistForest(completed=false){try{localStorage.setItem(FOREST_SAVE,JSON.stringify({schema:4,entry:forestEntry,checkpoint:snapshot,completed,inventory:{wealth,armor,sword:true}}));}catch{}}
function resumeForest(){try{const s=JSON.parse(localStorage.getItem(FOREST_SAVE));if(s?.schema!==4)return;forestEntry=s.entry||forestEntry;wealth=forestEntry.wealth;armor=forestEntry.armor;if(s.checkpoint&&!s.completed)restoreCheckpoint(s.checkpoint);}catch{}}
function retryForest(){if(level.done){startForest();return;}const cp=snapshot,d=level.deaths+1,t=level.time;startForest(forestEntry);level.deaths=d;level.time=t;if(cp)restoreCheckpoint(cp);persistForest();updateForestHUD();}

function forestAdvance(dt){
 if(level.done||hero.hp<=0)return;forestTime+=dt;
 for(const e of enemies){if(e.hidden&&Math.abs(hero.x-e.x)<300&&Math.abs(hero.y-e.y)<150){e.hidden=false;e.emerging=1;e.cooldown=1.2;gameSound.play('branch-snap-warning',e.x,e.y,.6);gameSound.play('undergrowth-rustle',e.x,e.y,.4);}else if(e.emerging>0){e.emerging=Math.max(0,e.emerging-dt);}}
 if(forestTime>=forestCallAt){const keys=['owl-hoot','distant-animal-shriek','owl-hoot','crow-call','old-trunk-creak'];gameSound.play(keys[Math.floor(Math.random()*keys.length)],hero.x+(Math.random()<.5?-260:260),hero.y-150,.32);forestCallAt=forestTime+9+Math.random()*9;}
 for(const b of forestBats){
  if(b.phase==='wait'){if(forestTime>=b.next&&Math.abs(hero.x-b.anchor)<430&&Math.abs(hero.y-(b.y+110))<35){b.phase='warn';b.t=0;b.face=hero.x<b.anchor?-1:1;b.x=b.anchor-b.face*530;b.hit=false;gameSound.play('bat-warning',b.x,b.y,.85);}continue;}
  b.t+=dt;if(b.phase==='warn'){if(b.t>=1){b.phase='fly';b.t=0;}continue;}
  b.x+=b.face*340*dt;if(!b.hit&&Math.abs(hero.x-b.x)<42&&circleHitsHero(b.x,b.y,12)){hurtHero(14);b.hit=true;}
  if(b.t>3.3){b.phase='wait';b.next=forestTime+5;b.t=0;}
 }
}
function forestHazards(dt){
 for(const p of platforms.filter(p=>p.loose)){
  if(p.fallen)continue;
  if(!p.triggered&&hero.ground&&Math.abs(hero.y-p.y)<3&&hero.x>p.x&&hero.x<p.x+p.w){p.triggered=true;p.timer=0;gameSound.play('rotten-plank-break',p.x,p.y,.5);}
  if(p.triggered){p.timer+=dt;if(p.timer>.9){p.fallen=true;if(hero.ground&&Math.abs(hero.y-p.y)<3&&hero.x>p.x&&hero.x<p.x+p.w){hero.ground=false;hero.vy=30;state('jump');}}}
 }
}
function updateForest(dt){
 if(level.done){updateForestHUD();return;}level.time+=dt;
 for(const p of pickups)if(!p.taken&&Math.abs(hero.x-p.x)<40&&Math.abs(hero.y-p.y)<35)collectLoot(p);
 FOREST_CHECKPOINTS.forEach((cp,i)=>{if(forestCP<i+1&&hero.hp>0&&hero.ground&&Math.abs(hero.x-cp.x)<38&&Math.abs(hero.y-cp.y)<4){forestCP=i+1;level.checkpoint=true;snapshot=captureCheckpoint();persistForest();gameSound.play('checkpoint-magic',cp.x,cp.y,.75);popupQueue.push({label:'CHECKPOINT',effect:'Progress saved',time:2});}});
 if(popup){popup.time-=dt;if(popup.time<=0)popup=null;}if(!popup&&popupQueue.length)popup=popupQueue.shift();
 const guard=enemies.find(e=>e.id==='forest-b3');
 if(hero.x>8940&&hero.hp>0&&hero.ground){if(guard?.hp>0){hero.x=8938;notice('Defeat the bandit guarding the road');}else{level.done=true;clearInput();persistForest(true);paused=true;notice('BLACK FOREST COMPLETE · Wealth '+wealth+(window.FOREST_STANDALONE?' · The village awaits':' · Next: Abandoned Sawmill'));window.princessInterludes?.start(4);}}
 else if(hero.hp>0&&document.getElementById('notice').textContent==='Defeat the bandit guarding the road')notice('');
 updateForestHUD();
}
async function loadForestAssets(){for(let i=1;i<=6;i++)forestArt['bg'+i]=await loadImage('assets/forest/bg'+i+'.webp');forestArt.trunk=await loadImage('assets/forest/trunk.webp');forestArt.ground=await loadImage('assets/forest/ground.webp');}
function drawForestBackdrop(vw,vh){
 const position=Math.max(0,Math.min(5,((camera.x??0)+W*.45-650)/1500)),i=Math.floor(position),t=position-i;
 for(const [key,a] of [['bg'+(i+1),1],['bg'+Math.min(6,i+2),t*t*(3-2*t)]]){const im=forestArt[key];if(!im)continue;const s=Math.max(vw/im.width,vh/im.height)*1.08,w=im.width*s,h=im.height*s;ctx.save();ctx.globalAlpha=a;ctx.drawImage(im,(vw-w)/2-Math.sin((camera.x||0)/1800)*vw*.02,(vh-h)/2,w,h);ctx.restore();}
 // Soft daylight shafts belong to the background plane, behind all trees and actors.
 ctx.save();const cam=(camera.x||0)*.16;
 for(let i=Math.floor(cam/460);i<Math.floor(cam/460)+4;i++){const x=i*460-cam-180;
  const light=ctx.createLinearGradient(x,0,x+160,vh);light.addColorStop(0,'#e0deb316');light.addColorStop(.72,'#d7ddaf09');light.addColorStop(1,'#d7ddaf00');ctx.fillStyle=light;
  ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x+25,0);ctx.lineTo(x+260,vh);ctx.lineTo(x+145,vh);ctx.closePath();ctx.fill();
 }ctx.restore();
 const g=ctx.createLinearGradient(0,0,0,vh);g.addColorStop(0,'#07120b10');g.addColorStop(1,'#07120b70');ctx.fillStyle=g;ctx.fillRect(0,0,vw,vh);
}
function drawForestPlatform(p){
 if(p.x+p.w<(camera.x||0)-50||p.x>(camera.x||0)+W+50)return;
 if(p.ceiling){drawRiverBeam(p.x+3,p.bottom-3,9,95);drawRiverBeam(p.x+p.w-12,p.bottom-3,9,95);if(riverArt.log)ctx.drawImage(riverArt.log,p.x,p.y-7,p.w,p.bottom-p.y+9);return;}
 if(p.wood){drawRiverPlatform(p);return;}
 const im=forestArt.ground;if(!im)return;
 const bottom=Math.max(p.y+190,structureBottom()),tile=400,h=tile*im.height/im.width,edge=h*.12;
 ctx.save();ctx.beginPath();ctx.rect(p.x,p.y-edge,p.w,bottom-p.y+edge);ctx.clip();
 for(let x=p.x;x<p.x+p.w;x+=tile){ctx.drawImage(im,x,p.y-edge,tile,h);for(let y=p.y-edge+h;y<bottom;y+=h*.3)ctx.drawImage(im,0,im.height*.7,im.width,im.height*.3,x,y,tile,h*.3);}
 ctx.restore();
}
function drawForestObjects(){
 for(const p of platforms.filter(p=>p.suspended)){ctx.strokeStyle='#9b845b';ctx.lineWidth=3;for(const dy of [-48,-26]){ctx.beginPath();ctx.moveTo(p.x,p.y+dy);ctx.quadraticCurveTo(p.x+p.w/2,p.y+dy+18,p.x+p.w,p.y+dy);ctx.stroke();}for(let x=p.x;x<=p.x+p.w;x+=75)drawRiverBeam(x,p.y-48,5,53);}
 
 for(const p of pickups)if(!p.taken){ctx.save();ctx.shadowColor='#dab76a';ctx.shadowBlur=9;drawLootIcon(lootInfo[p.kind][2],p.x-28,p.y-55,56);ctx.restore();}
 if(!window.CAMPAIGN_CLEAN)FOREST_CHECKPOINTS.forEach((cp,i)=>{drawLootIcon(8,cp.x-40,cp.y-88,88);if(forestCP>i){ctx.fillStyle='#ffe1a1';ctx.beginPath();ctx.arc(cp.x,cp.y-63,5,0,Math.PI*2);ctx.fill();}});
}
function drawForestCovers(front){
 if(!forestArt.trunk)return;
 const covers=front?forestAmbushTrees:forestCovers;
 for(const c of covers){if(c.x>(camera.x||0)+W+100||c.x+c.w<(camera.x||0)-100)continue;ctx.save();ctx.globalAlpha=1;ctx.drawImage(forestArt.trunk,c.x,c.y-c.h,c.w,c.h+25);ctx.restore();}
}
function drawForestBats(){const im=riverArt.bat;if(!im)return;const fw=im.width/4;for(const b of forestBats){if(b.phase==='wait')continue;ctx.save();ctx.translate(b.x,b.y);ctx.scale(b.face,1);ctx.drawImage(im,Math.floor(forestTime*9)%4*fw,0,fw,im.height,-70,-70,140,140);ctx.restore();}}

async function loadForestCommon(){
 for(const [k,p] of Object.entries({ladder:'terrain-ladder.png',bridge:'terrain-bridge.png',cliff:'v12/cliff.png',stoneCap:'v11/stone-cap.png',stoneWall:'v11/stone-wall.webp',loot:'loot.png'}))scenery[k]=await loadImage('assets/'+p);
 for(const k of ['bat','deck','log'])riverArt[k]=await loadImage('assets/river/'+k+'.webp');
 await loadSplatReference();
 for(const k of ['lava','leaf'])atmosphere[k]=await loadImage('assets/atmosphere/'+k+'.webp');
}

