function resumeSawmill(){try{const s=JSON.parse(localStorage.getItem(SAWMILL_SAVE));if(s?.schema!==7)return;sawmillEntry=s.entry||sawmillEntry;wealth=sawmillEntry.wealth;armor=sawmillEntry.armor;if(s.checkpoint&&!s.completed)restoreCheckpoint(s.checkpoint);}catch{}}
function retrySawmill(){if(level.done){startSawmill();return;}const cp=snapshot,d=level.deaths+1,t=level.time;startSawmill(sawmillEntry);level.deaths=d;level.time=t;if(cp)restoreCheckpoint(cp);persistSawmill();updateSawmillHUD();}
function sawmillOccluders(){return sawmillCovers.map(t=>({x:t.x-8,w:t.w+16,top:t.y-t.h,bottom:t.y+10})).concat(SAWMILL_CHECKPOINTS.map(t=>({x:t.x-80,w:160,top:t.y-100,bottom:t.y+20})),SAWMILL_TRACKS.map(t=>({x:t.lo-50,w:t.hi-t.lo+260,top:t.y-140,bottom:t.y+10}))).concat(SAWMILL_DOORS.map(d=>({x:d.x-150,w:300,top:d.y-280,bottom:d.y+20})),sawmillGuards,SAWMILL_FRONT_BEAMS.map(x=>({x:x-30,w:60,top:-750,bottom:550})),SAWMILL_SAWS.map(t=>({x:t.x-110,w:220,top:t.y-150,bottom:t.y+20})));}
function sawmillArrowSolid(x,y){return sawmillCovers.some(c=>x>=c.x&&x<=c.x+c.w&&y>=c.y-c.h&&y<=c.y);}
function releaseSawmillBarrel(track){
 const x=track.dir>0?track.lo:track.hi;track.releasedAt=sawmillTime;
 sawmillBarrels.push({id:'barrel-'+(++sawmillSerial),track:track.id,x,y:track.y-25,origin:x,floor:track.y,r:25,dir:track.dir,speed:track.speed,lo:track.lo,hi:track.hi,angle:0,hitHero:false,hitEnemies:[],soundAt:0});
 gameSound.play('barrel-release',x,track.y,.65);
}
function breakSawmillBarrel(b){gameSound.play('barrel-break',b.x,b.y,.5);sawmillDebris.push({x:b.x,y:b.y,t:0,angle:b.angle});}
function advanceSawmill(dt){
 if(level.done||hero.hp<=0)return;sawmillTime+=dt;
 SAWMILL_DOORS.forEach((d,i)=>{const target=Math.abs(hero.x-d.x)<250&&Math.abs(hero.y-d.y)<150?1:0;if(target&&sawmillDoors[i]===0)gameSound.play('mill-door',d.x,d.y,.55);sawmillDoors[i]=Math.max(0,Math.min(1,sawmillDoors[i]+(target?1:-1)*dt*1.5));});
 SAWMILL_SAWS.forEach((s,i)=>{const phase=sawmillSawState(s);const cycle=Math.floor((sawmillTime+s.offset)/6.6);if(phase.phase>=2.7&&sawmillSawSounds[i]!==cycle){sawmillSawSounds[i]=cycle;gameSound.play('saw-rise',s.x,s.y,.42);}if(phase.extension>0&&circleHitsHero(s.x,phase.cy,s.r-3)){if(hurtHero(20)){trapHits++;gameSound.play('saw-hit',s.x,s.y,.55);}}});
 if(sawmillTime>=sawmillCallAt){const inside=insideSawmill(hero.x);gameSound.play(inside?'sawmill-creak':'sawmill-timber-knock',hero.x+220,hero.y-120,.3);sawmillCallAt=sawmillTime+7+Math.random()*7;}
 for(const t of sawmillTracks){
  if(t.secondAt!==null&&sawmillTime>=t.secondAt){releaseSawmillBarrel(t);t.secondAt=null;}
  if(t.phase==='idle'){if(sawmillTime>=t.next&&hero.x>t.lo-250&&hero.x<t.hi+180&&Math.abs(hero.y-t.y)<100){t.phase='warn';t.timer=0;t.dir=t.alternate&&t.cycle%2?1:-1;gameSound.play('barrel-warning',t.dir>0?t.lo:t.hi,t.y,.85);}continue;}
  t.timer+=dt;if(t.timer>=1.25){releaseSawmillBarrel(t);t.secondAt=t.pair?sawmillTime+t.pair:null;t.phase='idle';t.next=sawmillTime+t.period;t.cycle++;}
 }
 for(const b of sawmillBarrels){
  const steps=Math.max(1,Math.ceil(b.speed*dt/5));
  for(let i=0;i<steps;i++){
   b.x+=b.dir*b.speed*dt/steps;b.angle+=b.dir*b.speed*dt/steps/b.r;
   b.y=b.floor-b.r;
   if(!b.hitHero&&circleHitsHero(b.x,b.y,b.r)){b.hitHero=true;if(hurtHero(15)){const x=hero.x+b.dir*22;if(platforms.some(p=>!p.ceiling&&Math.abs(p.y-hero.y)<5&&x>p.x+20&&x<p.x+p.w-20)&&!crates.some(c=>!c.broken&&Math.abs(c.x-x)<48&&Math.abs(c.y-hero.y)<60))hero.x=x;}}
   for(const e of enemies)if(e.hp>0&&!b.hitEnemies.includes(e.id)&&Math.abs(e.x-b.x)<b.r+19&&b.y+b.r>e.y-e.height&&b.y-b.r<e.y-4){b.hitEnemies.push(e.id);damageEnemy(e,35,b.id,'barrel');}
  }
  if(sawmillTime>=b.soundAt){gameSound.play('barrel-roll',b.x,b.y,.22);b.soundAt=sawmillTime+.6;}
  if(b.x<b.lo-25||b.x>b.hi+25){b.done=true;breakSawmillBarrel(b);}
 }
 sawmillBarrels=sawmillBarrels.filter(b=>!b.done);for(const d of sawmillDebris)d.t+=dt;sawmillDebris=sawmillDebris.filter(d=>d.t<.45);
}
function updateSawmill(dt){
 if(level.done){updateSawmillHUD();return;}level.time+=dt;
 for(const p of pickups)if(!p.taken&&Math.abs(hero.x-p.x)<40&&Math.abs(hero.y-p.y)<35)collectLoot(p);
 SAWMILL_CHECKPOINTS.forEach((cp,i)=>{if(sawmillCP<i+1&&hero.hp>0&&hero.ground&&Math.abs(hero.x-cp.x)<38&&Math.abs(hero.y-cp.y)<4){sawmillCP=i+1;level.checkpoint=true;snapshot=captureCheckpoint();persistSawmill();gameSound.play('checkpoint-magic',cp.x,cp.y,.75);popupQueue.push({label:'CHECKPOINT',effect:'Progress saved',time:2});}});
 if(popup){popup.time-=dt;if(popup.time<=0)popup=null;}if(!popup&&popupQueue.length)popup=popupQueue.shift();
 if(sawmillGateAt===null&&!enemies.some(e=>e.id==='sawmill-r2'&&e.hp>0)){sawmillGateAt=sawmillTime;gameSound.play('city-gate-open',8700,366,.75);}
 if(hero.x>8870&&hero.hp>0&&hero.ground){if(enemies.some(e=>e.id==='sawmill-r2'&&e.hp>0)){hero.x=8868;notice('Defeat the Brute guarding the city gate');}else if(sawmillTime-sawmillGateAt>=2.3){level.done=true;clearInput();persistSawmill(true);paused=true;notice('SAWMILL COMPLETE · City gate open · Next: Shadows of the City');window.princessInterludes?.start(5);}}
 else if(hero.hp>0&&document.getElementById('notice').textContent==='Defeat the Brute guarding the city gate')notice('');updateSawmillHUD();
}
async function loadSawmillAssets(common=true){
 if(common){await loadForestCommon();for(const k of ['crow-up','crow-down'])atmosphere[k]=await loadImage('assets/atmosphere/'+k+'.webp');forestArt.ground=await loadImage('assets/forest/ground.webp');}
 for(const k of ['bg1','bg4','bg6','barrel','wheel','door-closed','timber','saw'])sawmillArt[k]=await loadImage('assets/sawmill/'+k+'.webp');
}
function sawmillSawState(s,time=sawmillTime){
 const phase=((time+s.offset)%6.6+6.6)%6.6;
 // 2.7 s fully safe, .6 s audible warning, .7 s rise, 1.8 s exposed, .8 s retract.
 const extension=phase<3.3?0:phase<4?(phase-3.3)/.7:phase<5.8?1:1-(phase-5.8)/.8;
 return {phase,extension,cy:s.y+s.r+12-extension*(s.r+57)};
}
function drawSawmillBackdrop(vw,vh){
 // Scene boundaries belong to the door openings in world space, not to the hero.
 // The opaque facade masks the seam; through the opening the next room is already visible.
 const cx=camera.x??0,scale=vw/W;
 const entry=(SAWMILL_DOORS[0].x-94-cx)*scale,exit=(SAWMILL_DOORS[1].x-94-cx)*scale;
 for(const [key,from,to] of [['bg1',0,entry],['bg4',entry,exit],['bg6',exit,vw]]){
  const left=Math.max(0,from),right=Math.min(vw,to);if(right<=left)continue;
  const im=sawmillArt[key];if(!im)continue;
  const zoom=Math.max(vw/im.width,vh/im.height)*1.055,w=im.width*zoom,h=im.height*zoom;
  const px=(vw-w)/2-Math.sin(cx/3300)*(w-vw)*.28;
  const py=(vh-h)/2+(key==='bg4'?Math.max(-1,Math.min(1,-((camera.y??0)+400)/500))*(h-vh)*.35:0);
  ctx.save();ctx.beginPath();ctx.rect(left,0,right-left,vh);ctx.clip();ctx.drawImage(im,px,py,w,h);ctx.restore();
 }
}
function drawSawmillTimber(x,top,bottom,width=24){
 const im=sawmillArt.timber;if(!im||bottom<=top)return;
 for(let y=top;y<bottom;y+=220){const h=Math.min(220,bottom-y);ctx.drawImage(im,0,im.height*.15,im.width,im.height*.7*h/220,x-width/2,y,width,h);}
 ctx.fillStyle='#09080445';ctx.fillRect(x+width/2-3,top,3,bottom-top);ctx.fillStyle='#e2c28b22';ctx.fillRect(x-width/2+1,top,1,bottom-top);
}
function drawSawmillPlatform(p){
 if(!p.interior){drawForestPlatform(p);return;}
 // A rear edge and offset understructure produce depth without shifting the collision edge.
 ctx.fillStyle='#1e1712';ctx.beginPath();ctx.moveTo(p.x,p.y+12);ctx.lineTo(p.x+24,p.y-12);ctx.lineTo(p.x+p.w+24,p.y-12);ctx.lineTo(p.x+p.w,p.y+12);ctx.closePath();ctx.fill();
 const im=riverArt.deck;if(im)for(let x=p.x;x<p.x+p.w;x+=220){const w=Math.min(220,p.x+p.w-x);ctx.drawImage(im,0,0,im.width*w/220,im.height,x,p.y-10,w,31);}
 ctx.fillStyle='#110c0870';ctx.fillRect(p.x,p.y+20,p.w,10);
 for(const x of [p.x+32,p.x+p.w-32]){
  const below=platforms.filter(q=>q!==p&&q.y>p.y+100&&x>=q.x&&x<=q.x+q.w).map(q=>q.y);
  drawSawmillTimber(x,p.y+22,below.length?Math.min(...below):500,18);
  drawSawmillJoint(x,p.y+22,22);
 }
}
function drawSawmillBolt(x,y,r=2.5){
 ctx.fillStyle='#090b08';ctx.beginPath();ctx.arc(x+1,y+1,r+1,0,Math.PI*2);ctx.fill();
 const g=ctx.createLinearGradient(x-r,y-r,x+r,y+r);g.addColorStop(0,'#bbb19b');g.addColorStop(.45,'#787970');g.addColorStop(1,'#282e29');ctx.fillStyle=g;
 ctx.beginPath();for(let i=0;i<6;i++){const a=i*Math.PI/3;if(i)ctx.lineTo(x+Math.cos(a)*r,y+Math.sin(a)*r);else ctx.moveTo(x+r,y);}ctx.closePath();ctx.fill();
}
function drawSawmillJoint(x,y,w){
 const g=ctx.createLinearGradient(0,y,0,y+26);g.addColorStop(0,'#070604a0');g.addColorStop(1,'#07060400');ctx.fillStyle=g;ctx.fillRect(x-w*.8,y,w*1.6,26);
 ctx.fillStyle='#303029';ctx.fillRect(x-w/2,y+2,w,7);ctx.fillStyle='#aba08a55';ctx.fillRect(x-w/2,y+2,w,1);
 drawSawmillBolt(x-w*.30,y+5,1.8);drawSawmillBolt(x+w*.30,y+5,1.8);
}
function drawSawmillScenery(){
 for(const d of SAWMILL_DOORS)drawSawmillFacade(d);
 for(const c of sawmillCovers)for(let y=c.y-c.h;y<c.y;y+=24)ctx.drawImage(riverArt.log,c.x,y,c.w,28);
 // Rear structural posts use shallower contrast; near posts are drawn after the actors.
 for(const x of [3310,3890,4350,5780,6550,7270]){ctx.save();ctx.globalAlpha=.75;drawSawmillTimber(x+32,-720,500,28);ctx.restore();}
 if(sawmillArt.wheel){ctx.save();ctx.translate(6070,310);ctx.rotate(sawmillTime*.13);ctx.drawImage(sawmillArt.wheel,-130,-130,260,260);ctx.restore();}
 for(const d of SAWMILL_DOORS){ctx.fillStyle='#08060399';ctx.beginPath();ctx.ellipse(d.x,d.y+4,118,13,0,0,Math.PI*2);ctx.fill();}
 for(const t of sawmillTracks)drawSawmillPile(t);
}
function drawSawmillPile(t){
 const im=sawmillArt.barrel;if(!im)return;
 const slots=[[0,0],[50,0],[100,0],[150,0],[50,-43],[100,-43],[75,-86]];
 slots.forEach(([dx,dy],i)=>{const since=sawmillTime-(t.releasedAt??-99);ctx.save();
  if(i===0&&since<1.4)ctx.globalAlpha=Math.max(0,(since-.7)/.7);
  const rock=i===0&&t.phase==='warn'?Math.sin(t.timer*18)*.065:0;
  ctx.translate(t.hi+dx,t.y-25+dy);ctx.rotate(rock);ctx.drawImage(im,-25,-25,50,50);ctx.restore();
 });
}
function drawSawmillSaws(){
 const im=sawmillArt.saw;if(!im)return;
 for(const s of SAWMILL_SAWS){const p=sawmillSawState(s);drawSawmillSawMount(s,p);ctx.save();
  // Slot masks the retracted blade; the collision uses that same exposed circle.
  ctx.beginPath();ctx.rect(s.x-s.r-4,s.y-155,s.r*2+8,155);ctx.clip();
  ctx.translate(s.x,p.cy);ctx.rotate(sawmillTime*7+s.offset);ctx.drawImage(im,-s.r,-s.r,s.r*2,s.r*2);ctx.restore();
  if(p.cy<s.y+4){ctx.save();ctx.beginPath();ctx.rect(s.x-20,s.y-155,40,155);ctx.clip();const metal=ctx.createRadialGradient(s.x-3,p.cy-3,1,s.x,p.cy,13);metal.addColorStop(0,"#d1c6ac");metal.addColorStop(1,"#373731");ctx.fillStyle=metal;ctx.beginPath();ctx.arc(s.x,p.cy,12,0,Math.PI*2);ctx.fill();ctx.strokeStyle="#211f18";ctx.lineWidth=3;ctx.stroke();ctx.fillStyle="#191916";ctx.fillRect(s.x-3,p.cy-3,6,6);ctx.restore();}
  ctx.fillStyle='#120e09';ctx.fillRect(s.x-s.r-5,s.y-3,s.r*2+10,9);
  ctx.fillStyle=p.phase>=2.7&&p.phase<3.3?'#ddb761':'#625340';ctx.fillRect(s.x-s.r-5,s.y+7,s.r*2+10,3);
 }
}
function drawSawmillFront(){
 for(const x of SAWMILL_FRONT_BEAMS){ctx.fillStyle='#0805023a';ctx.fillRect(x+12,-700,17,1200);drawSawmillTimber(x,-700,500,32);
  for(const p of platforms)if(p.interior&&!p.ceiling&&x>p.x&&x<p.x+p.w)drawSawmillJoint(x,p.y+14,32);
 }
 SAWMILL_DOORS.forEach((d,i)=>{
  const t=sawmillDoors[i],w=236,h=250,im=sawmillArt['door-closed'];if(!im)return;
  const left=d.x-w/2,top=d.y-h;
  // Solid jambs stay opaque; each textured leaf foreshortens around its own hinge.
  ctx.drawImage(im,0,0,im.width,im.height*.14,left,top,w,h*.14);
  ctx.drawImage(im,0,im.height*.14,im.width*.105,im.height*.86,left,top+h*.14,w*.105,h*.86);
  ctx.drawImage(im,im.width*.895,im.height*.14,im.width*.105,im.height*.86,left+w*.895,top+h*.14,w*.105,h*.86);
  for(const side of [-1,1]){ctx.save();ctx.translate(d.x+side*w*.395,top+h*.14);ctx.transform(side===-1?1:-1,t*.13,0,1,0,0);ctx.scale(Math.cos(t*1.38),1);
   ctx.drawImage(im,im.width*(side===-1?.105:.5),im.height*.14,im.width*.395,im.height*.86,0,0,w*.395,h*.86);ctx.restore();}
 });
}
function drawSawmillObjects(){
 for(const p of pickups)if(!p.taken){ctx.save();ctx.shadowColor='#dab76a';ctx.shadowBlur=9;drawLootIcon(lootInfo[p.kind][2],p.x-28,p.y-55,56);ctx.restore();}
 if(!window.CAMPAIGN_CLEAN)SAWMILL_CHECKPOINTS.forEach((cp,i)=>{drawLootIcon(8,cp.x-40,cp.y-88,88);if(sawmillCP>i){ctx.fillStyle='#ffe1a1';ctx.beginPath();ctx.arc(cp.x,cp.y-63,5,0,Math.PI*2);ctx.fill();}});
}
function drawSawmillBarrels(){
 const im=sawmillArt.barrel;if(!im)return;
 for(const b of sawmillBarrels){if(Math.abs(b.x-(camera.x||0)-W/2)>W)continue;ctx.save();ctx.fillStyle='#15100666';ctx.beginPath();ctx.ellipse(b.x,b.floor+2,27,5,0,0,Math.PI*2);ctx.fill();ctx.translate(b.x,b.y);ctx.rotate(b.angle);ctx.drawImage(im,-b.r,-b.r,b.r*2,b.r*2);ctx.restore();}
 for(const d of sawmillDebris){for(let i=0;i<5;i++){ctx.save();ctx.globalAlpha=1-d.t/.45;ctx.translate(d.x+(i-2)*d.t*100,d.y-d.t*80+d.t*d.t*250);ctx.rotate(d.angle+i+d.t*8);ctx.drawImage(im,i*im.width/5,0,im.width/5,im.height,-5,-22,10,44);ctx.restore();}}
}

// Fixed freight barriers are construction, not breakable reward boxes.
function blockSawmillGuards(previousX){
 if(campaignLevel!==5)return;
 for(const o of sawmillGuards)if(hero.x+19>o.x&&hero.x-19<o.x+o.w&&hero.y>o.top&&hero.y-heroBodyHeight()<o.bottom){hero.x=previousX<o.x+o.w/2?o.x-19:o.x+o.w+19;hero.vx=0;}
}
