function drawCityWindLeaves(){
 if(!atmosphere.leaf)return;
 const cx=camera.x||0,cy=camera.y||0,h=canvas.clientHeight/(canvas.clientWidth/W),t=cityTime,drift=t*70;
 const firstX=Math.floor((cx-drift-100)/145),lastX=Math.ceil((cx+W-drift)/145);
 const firstY=Math.floor((cy-110)/130),lastY=Math.ceil((cy+h+30)/130);
 for(let col=firstX;col<=lastX;col++)for(let row=firstY;row<=lastY;row++){
  const seed=Math.sin(col*127.1+row*311.7)*43758.5453,phase=seed-Math.floor(seed);
  const x=col*145+phase*80+drift,y=row*130+((phase*7)%1)*85+Math.sin(t*.8+phase*6.28)*18;
  if(x<cx-6||x>cx+W+6||y<cy-6||y>cy+h+6)continue;
  ctx.save();ctx.translate(x,y);ctx.rotate(t+phase*6.28);ctx.drawImage(atmosphere.leaf,-5,-3,10,7);ctx.restore();
 }
}

'use strict';
/* Count incoming sword contacts, then visibly parry and answer with one blockable strike. */
function trySwordParry(e,kind,behind){
 const every=e.type==='boss'?3:['bandit','guard'].includes(e.type)?2:0;
 if(!every||kind!=='sword'||behind)return false;
 e.swordContacts=(e.swordContacts||0)+1;
 if(e.swordContacts%every)return false;
 const change=campaignLevel===8?c8State:enemyState;
 e.riposte={time:0,hit:false,windup:e.windup,duration:e.duration};
 e.sequence=null;e.strong=false;e.face=Math.sign(hero.x-e.x)||e.face;
 change(e,'guard');e.t=0;e.fired=false;
 gameSound.block(e.x,e.y);clash(e.x+e.face*35,e.y-80);
 return true;
}
function updateRiposte(e,dt){
 const r=e.riposte;if(!r)return;
 const change=campaignLevel===8?c8State:enemyState;
 if(hero.hp<=0||e.hp<=0||e.state==='hit'||e.state==='death'){
  e.windup=r.windup;e.duration=r.duration;e.riposte=null;return;
 }
 r.time+=dt;
 const blockTime=.16,hitTime=e.type==='boss'?.34:.30;
 if(r.time>=blockTime&&e.state==='guard'){
  change(e,'attack');e.windup=hitTime;e.duration=.68;
  if(e.type==='bandit')gameSound.play('club-whoosh',e.x,e.y,.55);else gameSound.sample('sword_swing',e.x,e.y,.55);
 }
 if(!r.hit&&r.time>=blockTime+hitTime){
  r.hit=true;e.fired=true;const dx=e.x-hero.x;
  if(Math.abs(dx)<(e.type==='bandit'?156:160)&&Math.abs(hero.y-e.y)<55&&(hero.x-e.x)*e.face>=-12){
   if(hero.state==='guard'&&hero.face*dx>0){
    gameSound.block(hero.x,hero.y);clash(hero.x+hero.face*35,hero.y-80);
    hero.guardStamina=Math.max(0,hero.guardStamina-(e.type==='boss'?24:16));
   }else hurtHero(e.damage);
  }
 }
 if(r.time>=blockTime+.68){
  e.windup=r.windup;e.duration=r.duration;e.riposte=null;e.cooldown=.7;
  change(e,e.type==='boss'&&campaignLevel===8?'recover':'idle');
 }
}

