  if(!p||p.source||p.paused||!enabled||!ready||context?.state!=='running'||document.hidden||!buffers.has(p.key))return;
  const offset=Math.max(0,p.time());const buffer=buffers.get(p.key);if(offset>=Math.min(p.duration,buffer.duration))return;
