'use strict';
// Zero-based scene indices. When level 7 exists, change 6:[5,6] to 6:[5],7:[6].
window.princessInterludes=(()=>{
 const AFTER_LEVEL={1:[0],2:[1],3:[2],4:[3],5:[4],6:[5],7:[6]};
 const SAVE='block-hunter-princess-interlude-v1';
 const panel=document.getElementById('princessInterlude');
 const screen=document.getElementById('princessCanvas');
 const state={ready:false,started:true,all:true,scene:0,t:0};
 let active=false,cutPaused=false,renderer=null,queue=[],position=0,completed=0,owner=null,inventory=null,checkpoint=null,initialLevelTime=0,initialDeaths=0;
 const enabled=()=>!!panel&&!window.DUNGEON_STANDALONE&&!window.CITY_STANDALONE&&!window.SAWMILL_STANDALONE&&!window.FOREST_STANDALONE;
 function store(){
  if(!active)return;
  try{localStorage.setItem(SAVE,JSON.stringify({schema:1,level:completed,position,time:state.t,
   inventory,checkpoint,levelTime:initialLevelTime,deaths:initialDeaths}));}catch{}
 }
 function removeSave(){try{localStorage.removeItem(SAVE);}catch{}}
 function sound(){gameSound.startInterlude(state.scene+1,()=>state.t);if(cutPaused)gameSound.pauseInterlude(true);}
 function label(){
  document.getElementById('princessPause').textContent=cutPaused?'Resume':'Pause';
  document.getElementById('princessCaption').textContent=renderer?.scenes[state.scene].line||'';
 }
 async function load(){
  if(!enabled())return;
  const DATA={animations:{}},images={};
  for(const action of ['idle','walk','kneel','sit','lie']){
   DATA.animations[action]={frames:princessArt[action]};
   for(const f of princessArt[action])images[f.file]=f.img;
  }
  images.room=await loadImage('assets/princess/locked-chamber.webp');
  screen.width=1280;screen.height=720;
  renderer=window.createPrincessSceneRenderer(screen,DATA,images,state);state.ready=true;
 }
 function show(){
  active=true;paused=true;cutPaused=false;clearInput();gameSound.reset();resetDialogues();
  panel.hidden=false;document.getElementById('game').classList.add('princessPlaying');
  notice('');label();sound();store();renderer.render();
 }
 function start(levelNumber){
  if(!enabled()||!state.ready||active||!campaign||campaignLevel!==levelNumber||!level.done||hero.hp<=0||owner===level)return false;
  const sequence=AFTER_LEVEL[levelNumber];if(!sequence)return false;
  owner=level;completed=levelNumber;queue=[...sequence];position=0;state.scene=queue[0];state.t=0;
  inventory={wealth,armor,sword:hasSword,hp:hero.hp,maxHP:hero.maxHP,gun:!!level.gun,ammo:level.ammo||0};checkpoint=captureCheckpoint();
  initialLevelTime=level.time;initialDeaths=level.deaths;show();return true;
 }
 function cancel(clearSave=true){
  const wasActive=active;active=false;cutPaused=false;gameSound.endInterlude();
  if(panel)panel.hidden=true;document.getElementById('game')?.classList.remove('princessPlaying');
  if(wasActive&&clearSave)removeSave();
 }
 function finish(){
  const after=completed,entry={...inventory};cancel();clearInput();
  if(window.HD_SPLIT_MODE&&after!==6){window.HDSplit?.goNext(after,entry);return;}
  if(after===1)startBridge(entry);
  else if(after===2)startRiver(entry);
  else if(after===3)startForest(entry);
  else if(after===4)startSawmill(entry);
  else if(after===5)startCity(entry);
  else{
   if(after===6&&window.dudeArrest?.start())return;
   if(after===7){startCastle8Campaign();return;}
   level.done=true;paused=true;updateLevelHUD();
   notice('TO BE CONTINUED · The princess is still waiting');
  }
 }
 function next(carry=0){
  if(!active)return;
  if(position+1>=queue.length){finish();return;}
  position++;state.scene=queue[position];state.t=carry;label();sound();store();
 }
 function update(dt){
  if(!active)return;
  if(owner!==level){cancel();return;}
  if(cutPaused||document.hidden)return;
  state.t+=Math.max(0,dt);
  while(active&&state.t>=8)next(state.t-8);
  if(active)gameSound.update();
 }
 function setPaused(value){
  if(!active)return;cutPaused=!!value;gameSound.pauseInterlude(cutPaused);clearInput();label();store();
 }
 function resumePending(){
  if(!enabled()||!state.ready||active||!campaign)return false;
  let saved;try{saved=JSON.parse(localStorage.getItem(SAVE));}catch{return false;}
  if(!saved||saved.schema!==1||saved.level!==campaignLevel||!AFTER_LEVEL[saved.level])return false;
  const seq=AFTER_LEVEL[saved.level];
  if(!Number.isInteger(saved.position)||saved.position<0||saved.position>=seq.length||!Number.isFinite(saved.time)||saved.time<0||saved.time>=8||!saved.checkpoint||saved.checkpoint.levelId!==saved.level)return false;
  restoreCheckpoint(saved.checkpoint);level.done=true;
  level.time=Number(saved.levelTime)||0;level.deaths=Number(saved.deaths)||0;
  owner=level;completed=saved.level;queue=[...seq];position=saved.position;
  state.scene=queue[position];state.t=saved.time;
  inventory={wealth,armor,sword:hasSword,hp:hero.hp};checkpoint=saved.checkpoint;
  initialLevelTime=level.time;initialDeaths=level.deaths;show();
  // A reload has no user gesture: wait for Resume so the voice cannot be missed.
  setPaused(true);return true;
 }
 if(panel){
  document.getElementById('princessPause').onclick=()=>setPaused(!cutPaused);
  document.getElementById('princessSkip').onclick=()=>next();
  document.getElementById('princessSound').onclick=()=>gameSound.toggle();
 }
 return {load,start,cancel,update,resumePending,setPaused,togglePause:()=>setPaused(!cutPaused),discardPending:()=>{cancel();removeSave();},
  render:()=>{if(active&&renderer)renderer.render()},get active(){return active},
  getState:()=>({active,paused:cutPaused,completedLevel:completed,scene:state.scene+1,time:state.t,queue:queue.map(i=>i+1)}),
  afterLevel:AFTER_LEVEL};
})();

