'use strict';
// Title → approved 45-second story → Level 1. Continue preserves current saves.
window.hisDudenessOpening=(()=>{
 const $=id=>document.getElementById(id),panel=$('opening');
 const enabled=!!panel&&(!window.HD_SPLIT_MODE||Number(window.HD_SPLIT_LEVEL)===1)&&!window.DUNGEON_STANDALONE&&!window.CITY_STANDALONE&&!window.SAWMILL_STANDALONE&&!window.FOREST_STANDALONE;
 const state={ready:false,playing:false,time:0,ended:false};
 let mode=enabled?'title':'done',renderer=null,gameReady=false,failed=false;
 const blocked=()=>mode!=='done';
 function conceal(value){
  $('game')?.classList.toggle('openingPlaying',value);
  for(const node of [document.querySelector('.gameHUD'),$('campaignBar'),$('stage'),$('utilityControls'),document.querySelector('footer')])if(node)node.inert=value;
 }
 function labels(){
  if(!panel)return;
  $('openingPause').textContent=state.playing?'Pause':'Resume';
  $('openingPause').hidden=mode!=='intro';$('openingSkip').hidden=mode!=='intro';
  $('openingTitle').hidden=mode!=='title';$('openingCanvas').hidden=mode==='title';
 }
 function hasProgress(){
  if(campaignLevel!==1||level.checkpoint)return true;
  return !!pendingLevel();
 }
 function pendingLevel(){
  if(window.dudeArrest?.hasPending())return 6;
  try{
   const s=JSON.parse(localStorage.getItem('block-hunter-princess-interlude-v1'));
   if(s?.schema===1&&Number.isInteger(s.level)&&s.level>=1&&s.level<=7&&s.checkpoint?.levelId===s.level&&Number.isInteger(s.position)&&s.position>=0&&s.position<1&&Number.isFinite(s.time)&&s.time>=0&&s.time<8)return s.level;
  }catch{}
  try{if(localStorage.getItem('his-dudeness-campaign-level')==='8'&&localStorage.getItem(C8_SAVE))return 8;}catch{}
  try{if(localStorage.getItem('his-dudeness-campaign-level')==='7'&&(localStorage.getItem(DUNGEON_SAVE)||localStorage.getItem('his-dudeness-dungeon-v45')))return 7;}catch{}
  return 0;
 }
 async function load(){
  if(!enabled)return;
  try{
   const DATA={actors:{dude:{},princess:{},knight:{idle:[]}}},images={};
   const baseline=assets.idle[0].h*assets.idle[0].scale;
   for(const action of ['idle','walk']){
    DATA.actors.dude[action]=assets[action].map(f=>{images[f.src]=f.img;return {file:f.src,w:f.w,h:f.h,ax:f.anchor,ay:f.h-(f.footInset||0),scale:f.scale/baseline}});
    DATA.actors.princess[action]=princessArt[action].map(f=>{const key='princess/'+f.file;images[key]=f.img;return {file:key,w:f.width,h:f.height,ax:f.anchor[0],ay:f.anchor[1],scale:1/479}});
   }
   DATA.actors.knight.idle=enemyArt.boss.actions.idle.map(f=>{const key='knight/'+f.file;images[key]=f.img;return {file:key,w:f.width,h:f.height,ax:f.anchorX,ay:f.anchorY,scale:1/enemyArt.boss.actions.idle[0].height}});
   images.castle=scenery.background;
   const backgrounds={room:'assets/princess/locked-chamber.webp',village:'assets/story-intro/village.webp',grandmother:'assets/story-intro/grandmother.webp'};
   await Promise.all(Object.entries(backgrounds).map(async([key,path])=>images[key]=await loadImage(path)));
   const screen=$('openingCanvas');screen.width=1280;screen.height=720;
   renderer=window.createHisDudenessStoryRenderer(screen,DATA,images,state,$('openingCaption'));state.ready=true;
  }catch(error){failed=true;console.error('Intro assets could not load',error);}
 }
 function onGameReady(){
  if(!enabled)return false;
  gameReady=true;paused=true;clearInput();gameSound.reset();conceal(true);panel.hidden=false;
  $('openingStart').disabled=false;$('openingContinue').disabled=false;$('openingContinue').hidden=!hasProgress();
  $('openingStatus').textContent=failed?'Intro unavailable · New game will open Level 1.':'A promise. A princess. A long road.';
  labels();return true;
 }
 function newGame(){
  if(!blocked()||!gameReady||mode!=='title')return;
  clearInput();paused=true;
  if(failed||!state.ready){enterGame(true);return;}
  mode='intro';state.time=0;state.playing=true;state.ended=false;
  resetDialogues();labels();gameSound.startIntro(()=>state.time);renderer.render();
  $('openingSkip').focus?.();
 }
 function enterGame(fresh){
  if(!blocked()||!gameReady)return;
  mode='done';state.playing=false;state.ended=true;gameSound.endInterlude();
  panel.hidden=true;conceal(false);clearInput();
  renderer=null;$('openingCanvas').width=1;$('openingCanvas').height=1;
  if(fresh){try{localStorage.removeItem(DUNGEON_SAVE);localStorage.removeItem('his-dudeness-dungeon-v45');localStorage.removeItem(C8_SAVE);localStorage.removeItem('his-dudeness-campaign-level');}catch{}window.dudeArrest?.discardPending();window.princessInterludes?.discardPending();startLevel();}
  else{const pending=pendingLevel();if(pending&&pending!==campaignLevel){if(pending===8)resumeCastle8Campaign();else if(pending===7)resumeDungeonCampaign();else selectCampaignLevel(pending);}paused=false;notice('');document.getElementById('pause').textContent='Ⅱ';if(!window.dudeArrest?.resumePending()&&!window.princessInterludes?.resumePending()&&campaignLevel===7&&level.done)showDungeonCampaignEnd();}
  if(campaignLevel===8&&castle8.stage==='complete'){paused=true;document.getElementById('castle8End').hidden=false;}clearInput();gameSound.update();
  $('canvas').focus?.({preventScroll:true});
 }
 function skip(){if(mode==='intro')enterGame(true);}
 function update(dt){
  if(mode!=='intro'||!state.playing||document.hidden)return;
  state.time=Math.min(45,state.time+Math.max(0,dt));
  if(state.time>=45){enterGame(true);return;}
  gameSound.update();
 }
 function setPaused(value){
  if(mode!=='intro')return;
  state.playing=!value;gameSound.pauseInterlude(!!value);clearInput();labels();
 }
 function handleKey(e){
  if(!blocked())return false;
  if(['Space','Escape','ArrowLeft','ArrowRight','ArrowUp','ArrowDown','KeyW','KeyQ','KeyS','KeyD','KeyE','KeyF'].includes(e.code)){
   e.preventDefault();if(e.repeat)return true;
   if(e.code==='Escape')skip();
   else if(e.code==='Space'){if(mode==='intro')setPaused(state.playing);else newGame();}
  }
  return true;
 }
 if(panel){
  $('openingStart').onclick=newGame;$('openingContinue').onclick=()=>enterGame(false);
  $('openingSkip').onclick=skip;$('openingPause').onclick=()=>setPaused(state.playing);
  $('openingSound').onclick=()=>gameSound.toggle();
  $('openingFullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen();}catch{}};
 }
 if(enabled)conceal(true);
 return {load,onGameReady,newGame,skip,enterCurrent:()=>enterGame(false),setPaused,handleKey,update,
  render:()=>{if(mode==='intro'&&renderer)renderer.render()},get active(){return blocked()},
  getState:()=>({mode,ready:state.ready,gameReady,failed,playing:state.playing,time:state.time}),
  get renderer(){return renderer}};
})();

