// Arrest after the existing Level 6 interludes. No synthetic/playable Level 7 is added.
window.dudeArrest=(()=>{
 const $=id=>document.getElementById(id),panel=$('arrestIntro'),SAVE='his-dudeness-arrest-v1';
 let ready=false,active=false,cutPaused=false,complete=false,time=0,renderer=null,owner=null,entry=null,checkpoint=null,handoff=null,lastSaved=-1;
 const copy=v=>JSON.parse(JSON.stringify(v));
 const enabled=()=>!!panel&&!window.DUNGEON_STANDALONE&&!window.CITY_STANDALONE&&!window.SAWMILL_STANDALONE&&!window.FOREST_STANDALONE;
 const cues=[[4.9,'sword_block_1',.25],[8.98,'sword_block_1',.32],[11.1,'sword_block_1',.22],[12.3,'city-chain',.2],[18.3,'city-gate-open',.36],[24.7,'sword_block_1',.22],[29.55,'city-chain',.32],[31.95,'city-gate-open',.42],[33,'sword_block_1',.3],[34.48,'sword_block_1',.22],[34.7,'sword_block_1',.09]];
 function saved(){try{return JSON.parse(localStorage.getItem(SAVE))}catch{return null}}
 function valid(s){return s?.schema===1&&s.checkpoint?.levelId===6&&Number.isFinite(s.time)&&s.time>=0&&s.time<=40&&s.inventory&&['wealth','armor','hp','ammo'].every(k=>Number.isFinite(s.inventory[k]));}
 function store(){if(!active)return;try{localStorage.setItem(SAVE,JSON.stringify({schema:1,time,complete,inventory:entry,checkpoint,handoff}));lastSaved=Math.floor(time);}catch{}}
 function discardPending(){cancel();try{localStorage.removeItem(SAVE)}catch{}}
 function conceal(value){
  $('game')?.classList.toggle('arrestPlaying',value);
  for(const node of [document.querySelector('.gameHUD'),$('campaignBar'),$('stage'),$('utilityControls'),document.querySelector('footer')])if(node)node.inert=value;
 }
 function labels(){
  $('arrestPause').textContent=cutPaused?'Resume':'Pause';$('arrestPause').hidden=complete;
  $('arrestSkip').hidden=complete;$('arrestEnd').hidden=!complete;
  $('arrestCaption').textContent=complete?'Dude is imprisoned. A key lies outside his cell.':'The castle guard arrests Dude.';
 }
 async function load(){
  if(!enabled())return;
  const response=await offlineJSON('assets/capture/capture.json');if(!response.ok)throw Error('Arrest manifest could not load');
  const data=await response.json(),images={};
  await Promise.all(Object.entries(data.images).map(async([key,path])=>{images[key]=await loadImage(path)}));
  const screen=$('arrestCanvas');screen.width=1280;screen.height=720;
  renderer=window.createDudeArrestRenderer(screen,data,images);ready=true;
 }
 function show(){
  active=true;paused=true;cutPaused=false;clearInput();resetDialogues();panel.hidden=false;conceal(true);labels();
  gameSound.startArrest();if(complete)gameSound.pauseArrest(true);renderer.draw(time);store();$('arrestSkip').focus?.();
 }
 function start(){
  if(!enabled()||!ready||active||!campaign||campaignLevel!==6||!level.done||hero.hp<=0||owner===level)return false;
  owner=level;entry={wealth,armor,sword:hasSword,hp:hero.hp,maxHP:hero.maxHP,gun:!!level.gun,ammo:level.ammo||0};checkpoint=captureCheckpoint();
  time=0;complete=false;handoff=null;show();return true;
 }
 function cancel(clearSave=true){
  const wasActive=active;active=false;cutPaused=false;
  if(wasActive){gameSound.reset();if(clearSave)try{localStorage.removeItem(SAVE)}catch{}}
  if(panel)panel.hidden=true;conceal(false);
 }
 function level7State(){return {schema:1,level:7,chapter:'Locked Cell',introComplete:true,
  player:{hp:entry.hp,maxHP:entry.maxHP,sword:false,gun:false,ammo:0,wealth:0,armor:0},
  confiscated:copy(entry),equipment:{location:'confiscation-shelf',claimed:false},
  cell:{locked:true,doorWidth:180},key:{id:'cell-key',location:'outside-cell',x:660,y:410,available:true,collected:false}};}
 function finish(){
  if(!active||complete)return;
  time=40;complete=true;cutPaused=true;handoff=level7State();clearInput();gameSound.reset();labels();renderer.draw(time);store();
  // Future dungeon module consumes exactly the same state on playback and Skip.
  if(window.HD_SPLIT_MODE&&Number(window.HD_SPLIT_LEVEL)===6){const next=copy(handoff);cancel(false);window.HDSplit?.goNext(6,entry,{dungeonEntry:next});return;}
   if(typeof window.startDungeonLevel==='function'){const next=copy(handoff);cancel(false);window.startDungeonLevel(next);}
 }
 function update(dt){
  if(!active)return;if(owner!==level){cancel();return;}
  if(cutPaused||complete||document.hidden)return;
  const before=time;time=Math.min(40,time+Math.max(0,Number.isFinite(dt)?dt:0));gameSound.update();
  // Long frames advance the story without playing an accumulated burst of effects.
  if(time-before<1){
   for(const[t,key,volume]of cues)if(t>before&&t<=time)gameSound.arrestSound(key,volume);
   const moving=t=>t<4||(t>9.3&&t<10.4)||(t>13&&t<18.5)||(t>19&&t<24)||(t>25&&t<29)||(t>34&&t<37.5);
   for(let n=Math.floor(before/.42)+1;n<=Math.floor(time/.42);n++)if(moving(n*.42))gameSound.arrestSound('step_stone_'+(n%2+1),.22);
  }
  if(time>=40){finish();return;}if(Math.floor(time)!==lastSaved)store();
 }
 function setPaused(value){if(!active||complete)return;cutPaused=!!value;clearInput();gameSound.pauseArrest(cutPaused);labels();store();}
 function resumePending(){
  if(!enabled()||!ready||active||campaignLevel!==6)return false;const s=saved();if(!valid(s))return false;
  restoreCheckpoint(s.checkpoint);level.done=true;owner=level;entry=copy(s.inventory);checkpoint=s.checkpoint;
  time=s.time;complete=!!s.complete&&time===40;handoff=complete?level7State():null;if(complete){const next=copy(handoff);discardPending();startDungeonLevel(next);return true;}show();setPaused(true);return true;
 }
 function replay(){if(!active||!complete)return;time=0;complete=false;handoff=null;show();}
 function back(){const e={wealth:entry?.wealth||0,armor:entry?.armor||0};discardPending();startCity(e);}
 function handleKey(e){if(!active)return false;if(['Escape','Space','ArrowLeft','ArrowRight','ArrowUp','ArrowDown','KeyW','KeyQ','KeyS','KeyD','KeyE','KeyF'].includes(e.code)){e.preventDefault();if(!e.repeat){if(e.code==='Escape')finish();else if(e.code==='Space')setPaused(!cutPaused);}}return true;}
 if(panel){$('arrestPause').onclick=()=>setPaused(!cutPaused);$('arrestSkip').onclick=finish;$('arrestSound').onclick=()=>gameSound.toggle();$('arrestReplay').onclick=replay;$('arrestReturn').onclick=back;}
 window.addEventListener('blur',()=>setPaused(true));document.addEventListener('visibilitychange',()=>{if(document.hidden)setPaused(true)});
 return {load,start,cancel,discardPending,finish,update,setPaused,resumePending,handleKey,
  hasPending:()=>valid(saved()),render:()=>{if(active&&renderer)renderer.draw(time)},
  get active(){return active},getState:()=>({ready,active,paused:cutPaused,complete,time,handoff:handoff?copy(handoff):null}),
  sceneAt:t=>renderer?.state(t)};
})();

