 drawPrincess();drawWindLeaves();drawBloodWorld();for(const b of bullets)rect(b.x-7,b.y,14,2,'#ffdc8d');for(const s of sparks)rect(s.x,s.y,3,3,'#edc482');if(campaignLevel===6){drawCityPlatformGuards();drawEnemyArrows();}else if(campaign&&campaignLevel===5){drawSawmillFront();drawSawmillGuards();drawEnemyArrows();}else if(campaign&&campaignLevel===4){drawForestCovers(true);drawEnemyArrows();}else if(campaign&&campaignLevel===3)drawRiverFront();else if(campaign&&campaignLevel===2)drawBridgeArchitecture(true);else{drawFrontSupports();drawForegroundRuins();}drawVisibleCrates();ctx.restore();ctx.setTransform(dpr,0,0,dpr,0,0);renderLens(dpr,vw,vh);drawLootPopup(vw,vh);drawDialogue(vw,vh,lensCtx?.measureText?lensCtx:ctx);
