function resetHazards(){hazardState={time:0,gateTime:0,completed:false};}
function floorAt(x){return (scenes[currentScene].floors||[{x:0,w:W}]).some(p=>x>=p.x&&x<=p.x+p.w);}
function spikePhase(index){const t=(hazardState.time+index*1.15)%4.8;return t<.7?{height:28*t/.7,warning:true}:t<2?{height:28,warning:false}:t<2.5?{height:28*(2.5-t)/.5,warning:false}:{height:0,warning:t>4.2};}
function hazardHurt(){if(hurtHero(20)){trapHits++;if(hero.hp>0){if(campaign&&currentScene==='crumble'){for(const p of platforms){p.fallen=false;p.triggered=false;p.timer=0;}}hero.x=100;hero.y=FLOOR;hero.vx=hero.vy=0;hero.ground=true;hero.climbing=false;state('idle')}}}
function blockHazards(previousX){if(scenes[currentScene].hazard!=='gate')return;const obstacles=[{x:440,w:155,bottom:280},...(hazardState.gateTime>0?[]:[{x:820,w:30,bottom:FLOOR}])];for(const o of obstacles){if(hero.x+19>o.x&&hero.x-19<o.x+o.w&&hero.y-heroBodyHeight()<o.bottom){hero.x=previousX<o.x+o.w/2?o.x-19:o.x+o.w+19;hero.vx=0}}}
function updateHazards(dt){if(campaignLevel===8){castle8Hazards(dt);return;}if(campaignLevel===7){dungeonHazards(dt);return;}if(campaignLevel===6){advanceCity(dt);return;}if(campaign&&campaignLevel===5){advanceSawmill(dt);return;}if(campaign&&campaignLevel===4){forestHazards(dt);return;}if(campaign&&campaignLevel===3){riverHazards(dt);return;}if(campaign&&campaignLevel===2){updateBridgeCollapse(dt);return;}const kind=scenes[currentScene].hazard;if(!kind)return;hazardState.time+=dt;hazardState.gateTime=Math.max(0,hazardState.gateTime-dt);
 if(kind==='spikes')for(let i=0;i<3;i++){const x=350+i*210,h=spikePhase(i).height;if(h>3&&hero.x+16>x&&hero.x-16<x+65&&hero.y>FLOOR-h)hazardHurt();}
 if(kind==='crumble'){for(const p of platforms){if(!p.loose||p.fallen)continue;if(hero.ground&&Math.abs(hero.y-p.y)<2&&hero.x>=p.x&&hero.x<=p.x+p.w)p.triggered=true;if(p.triggered){p.timer=(p.timer||0)+dt;if(p.timer>.7){p.fallen=true;if(hero.x>=p.x&&hero.x<=p.x+p.w&&hero.ground){hero.ground=false;hero.vy=0;state('jump')}}}}if(hero.y>H+70)hazardHurt();}
 if(kind==='gate'&&hero.ground&&hero.x>240&&hero.x<310&&hero.y===FLOOR)hazardState.gateTime=6;
 if(hero.x>1030&&hero.hp>0)hazardState.completed=true;document.getElementById('nextRoom').disabled=!hazardState.completed;
}
function drawHazards(){const kind=scenes[currentScene].hazard;if(!kind)return;
 if(kind==='spikes')for(let i=0;i<3;i++){const x=350+i*210,p=spikePhase(i);rect(x,FLOOR-3,65,6,'#1b1714');if(p.height>0&&scenery.spikes){ctx.save();ctx.beginPath();ctx.rect(x,FLOOR-p.height,65,p.height+8);ctx.clip();ctx.drawImage(scenery.spikes,x,FLOOR-p.height,65,35);ctx.restore()}}

 if(kind==='gate'){rect(240,FLOOR-4,70,7,hazardState.gateTime>0?'#e4ba60':'#776242');platform({x:440,y:245,w:155,ceiling:true});stoneWall(800,155,18,211,.25);stoneWall(852,155,18,211,.25);const bottom=hazardState.gateTime>0?190:FLOOR;for(let x=822;x<850;x+=9){rect(x,155,5,bottom-155,'#282b28');rect(x,155,1.5,bottom-155,'#aaa48e');}for(let y=180;y<bottom;y+=36)rect(820,y,31,4,'#45473b');}
 }
