function persistCastle8(){try{if(!window.CASTLE8_STANDALONE&&window.campaignBooted)localStorage.setItem('his-dudeness-campaign-level','8');localStorage.setItem(C8_SAVE,JSON.stringify({schema:1,entry:castle8Entry,duelCheckpoint:castle8BossCheckpoint,checkpoint:level.done?captureCastle8():(castle8BossCheckpoint||castle8Checkpoint||captureCastle8()),complete:level.done}));}catch{}}
function retryCastle8(){const s=castle8BossCheckpoint||castle8Checkpoint;const deaths=level.deaths+1;if(s&&!level.done)restoreCastle8(dc(s));else resetCastle8();level.deaths=deaths;persistCastle8();}
function castle8Ready(){
 document.getElementById('game').classList.remove('openingPlaying','princessPlaying','arrestPlaying');
 document.getElementById('campaignBar').hidden=false;document.getElementById('campaignSelect').value='8';document.getElementById('retryLevel').onclick=retryCastle8;
 document.getElementById('newLevel').onclick=resetCastle8;updateCastle8HUD();
}
function castle8Context(){
 if(!hero||hero.hp<=0||!hero.ground||castle8.stage!=='explore'||Math.abs(hero.y-366)>10)return null;
 if(hero.x>3830&&hero.x<4000)return {id:'door',text:enemies.some(e=>['c8-passage','c8-captain'].includes(e.id)&&e.hp>0)?'Defeat the royal guards':'Open her door'};
 return null;
}
function interactCastle8(){if(!loaded||paused||!castle8Context()||enemies.some(e=>['c8-passage','c8-captain'].includes(e.id)&&e.hp>0))return;startCastle8Arrival();}
function castle8Gate(){const t=castle8.time%8;return {t,warning:t>=2.8&&t<3.8,open:t<3.8?1:t<5?1-(t-3.8)/1.2:t<6.3?0:(t-6.3)/1.7};}
function blockCastle8(previousX){
 const g=castle8Gate(),bottom=366-g.open*210;
 if(castle8.stage==='explore'&&hero.x+19>3070&&hero.x-19<3130&&hero.y-heroBodyHeight()<bottom&&hero.y>80){hero.x=previousX<3100?3051:3149;hero.vx=0;}
 if(castle8.stage==='explore'&&hero.x>3910){hero.x=3910;hero.vx=0;}
 if(castle8.stage==='duel')hero.x=clamp(hero.x,4070,4905);
}
function castle8FallCheck(){if(hero.hp>0&&hero.y>690){hurtHero(20,true);if(hero.hp>0){hero.x=safeSpot.x;hero.y=safeSpot.y;hero.vx=hero.vy=0;hero.climbing=false;hero.ground=true;state('idle');camera.x=camera.y=null;}}}
function updateCastle8(dt){
 if(level.done)return;level.time+=dt;
 for(const p of pickups)if(!p.taken&&Math.abs(hero.x-p.x)<40&&Math.abs(hero.y-p.y)<35)collectLoot(p);
 if(hero.ground&&hero.hp>0&&castle8.stage==='explore'&&!enemies.some(e=>e.hp>0&&Math.abs(e.x-hero.x)<220))safeSpot={x:hero.x,y:hero.y};
 if(!castle8.cp&&hero.x>3710&&hero.ground&&castle8.stage==='explore'){
  castle8.cp=true;level.checkpoint=true;castle8Checkpoint=captureCastle8();snapshot=castle8Checkpoint;persistCastle8();gameSound.play('checkpoint-magic',hero.x,hero.y,.6);popupQueue.push({label:'CHECKPOINT',effect:'The princess is just beyond this door',time:2.7});
 }
 if(popup){popup.time-=dt;if(popup.time<=0)popup=null;}if(!popup&&popupQueue.length)popup=popupQueue.shift();
 updateCastle8HUD();
}
function updateCastle8HUD(){
 if(!hero||!castle8.stage)return;updateEnergy();
 level.index=castle8.stage==='explore'?Math.min(3,Math.max(0,C8_SECTIONS.slice(0,4).findLastIndex(s=>hero.x>=s.x))):castle8.stage==='arrival'?4:5;
 document.getElementById('levelProgress').textContent='THE LAST KISS · '+(level.index+1)+' / 6 · '+C8_SECTIONS[level.index].name;
 document.getElementById('wealthValue').textContent=wealth;document.getElementById('armorValue').textContent=armor+' / 4';document.getElementById('armorMeter').value=armor;document.getElementById('ammoValue').textContent=(level.gun?level.ammo:0)+' / 0';
 const badge=document.querySelector('.levelBadge');if(badge){badge.textContent='8';badge.setAttribute('aria-label','Level 8');}
 document.getElementById('retryLevel').textContent=level.done?'Play again':castle8BossCheckpoint?'Retry duel':level.checkpoint?'From checkpoint':'Restart level';
 document.querySelector('[data-key="shoot"]')?.setAttribute('aria-disabled',String(!level.gun||!level.ammo));
 const c=castle8Context(),use=document.getElementById('castle8Use');use.hidden=!c;use.disabled=paused;
 const hint=castle8.stage==='explore'?(c?c.text+' · USE / R':hero.x<440?'Find the princess. W jump · S roll · D sword · E block':hero.x>2930&&hero.x<3270?'Wait for the portcullis to rise.':hero.x>3300&&hero.x<3760?'Break the supply chests before entering.':''):castle8.stage==='duel'&&castle8.duelElapsed<9?'Low fire: JUMP (W) · High fire: CROUCH (↓)':'';
 document.getElementById('castle8Hint').textContent=hero.hp>0?hint:'';
 document.getElementById('castle8Skip').hidden=!['arrival','victory'].includes(castle8.stage);
 const b=enemies.find(e=>e.type==='boss'),hud=document.getElementById('castle8Boss');hud.hidden=castle8.stage!=='duel';
 if(b){document.getElementById('castle8BossHP').value=b.hp;document.getElementById('castle8BossLabel').textContent='DARK KNIGHT · '+b.hp+' / '+b.maxHP;}
}

'use strict';
function c8State(e,s){if(e.state!==s){e.state=s;e.t=0;e.fired=false;}}
function c8Boss(){return enemies.find(e=>e.type==='boss');}
function c8BossSay(trigger,force=false){
 const e=c8Boss();if(!e||hero.hp<=0||!force&&(castle8.bossTalkAt||0)>castle8.time)return false;
 const line=chooseDialogue('BOSS',trigger);if(!line)return false;
 castle8.bossBubble={speaker:e,character:'BOSS',scene:currentScene,trigger,text:line.text,remaining:Math.max(2.5,Math.min(4.5,line.text.length/15+1))};castle8.bossTalkAt=castle8.time+6;return true;
}
function damageCastle8Enemy(e,amount,id,kind='projectile'){
 if(e.hp<=0||e.hidden||e.seenHits.has(id)||castle8.stage==='arrival'||castle8.stage==='victory')return false;
 e.seenHits.add(id);const behind=(hero.x-e.x)*e.face<-18;
 if(trySwordParry(e,kind,behind)){if(e.type==='boss'){castle8.blocked++;c8BossSay('attack');}return false;}
 if(kind==='sword'&&behind)amount=38;
 e.hp=Math.max(0,e.hp-amount);hits++;bloodHit(e.x,e.y-e.height*.6,Math.sign(e.x-hero.x)||hero.face,e.hp===0);
 if(e.hp===0){c8State(e,'death');gameSound.death(e.type==='guard'?'bandit':'boss',e.x,e.y);wealth+=e.type==='boss'?200:35;
  if(e.type==='boss'){c8BossSay('death',true);startCastle8Victory();}
 }else{
  gameSound.voice(e.type==='guard'?'bandit':'boss','hit',e.x,e.y);
  // A committed cast or thrust keeps its telegraph; recovery hits can stagger.
  if(e.type==='guard'||behind&&!(e.staggerLock>0)||e.type==='boss'&&['idle','walk'].includes(e.state)&&!(e.staggerLock>0)){
   c8State(e,'hit');e.cooldown=.75;e.sequence=null;e.riposte=null;e.staggerLock=e.type==='boss'?2.8:0;
  }
  if(e.type==='boss'&&behind)c8Speak('very-heroic');
  if(e.type==='boss'){if(e.hp<=e.maxHP*.25&&!e.lowSpeech){e.lowSpeech=true;c8BossSay('low_health',true);}else if(e.hp<=e.maxHP*.5&&!e.phaseSpeech){e.phaseSpeech=true;c8BossSay('boss_phase_2',true);}else c8BossSay('take_damage');}
 }
 return true;
}
function c8Melee(e){
 if(hero.state==='roll'||hero.hp<=0)return;
 if(hero.state==='guard'&&hero.face*(e.x-hero.x)>0){gameSound.block(hero.x,hero.y);clash(hero.x+hero.face*35,hero.y-80);hero.guardStamina=Math.max(0,hero.guardStamina-(e.type==='boss'?34:18));
  if(hero.t<.24){c8State(e,'hit');e.cooldown=1.3;}if(!hero.guardStamina){state('stagger');hero.guardLock=.9;}return;
 }
 const prior=hero.hp;if(hurtHero(e.damage)&&e.type==='boss'&&prior>hero.hp){castle8.recoverCue=castle8.time+1;castle8.closeCall ||= hero.hp<30;}
}
function c8Cast(e){
 c8State(e,'cast');e.face=Math.sign(hero.x-e.x)||e.face;
 c8BossSay('attack');
 const phase=e.hp/e.maxHP>.65?1:e.hp/e.maxHP>.30?2:3;
 e.sequence=phase===1?['low']:phase===2?(e.castCount%2?['high','low']:['low','high']):['low','high','low'];e.castCount++;e.shot=0;e.charged=-1;
}
function c8Fire(e,height){
 const p={x:e.x+e.face*42,y:366-(height==='low'?24:108),vx:e.face*220,age:0,height,r:14,life:5};castle8.fireballs.push(p);
 gameSound.play('l8-fire-launch',e.x,e.y,.65);return p;
}
function updateCastle8Enemies(dt){
 for(const e of enemies){e.t+=dt;e.cooldown=Math.max(0,(e.cooldown||0)-dt);e.staggerLock=Math.max(0,(e.staggerLock||0)-dt);if(e.hp<=0)continue;if(e.riposte){updateRiposte(e,dt);continue;}
  if(hero.hp<=0){c8State(e,'idle');continue;}if(e.type==='boss'){updateCastle8Boss(e,dt);continue;}
  if(castle8.stage!=='explore'||Math.abs(hero.x-e.x)>800)continue;
  const dx=hero.x-e.x,dist=Math.abs(dx),same=Math.abs(hero.y-e.y)<48;
  if(e.state==='hit'){if(e.t>.4)c8State(e,'idle');continue;}
  if(e.state==='guard'){if(e.t>.75){c8State(e,'idle');e.cooldown=.65;}continue;}
  if(e.state==='attack'){
   if(e.t>=.82&&!e.fired){e.fired=true;gameSound.sample('sword_swing',e.x,e.y,.45);if(same&&dist<160&&dx*e.face>-12)c8Melee(e);}
   if(e.t>1.65){c8State(e,'idle');e.cooldown=.65;}continue;
  }
  if(same&&dist<350){e.face=Math.sign(dx)||e.face;
   if(dist<150&&e.cooldown<=0){e.attackCount++;c8State(e,'attack');}
   else if(dist>132){e.x=clamp(e.x+e.face*48*dt,e.minX,e.maxX);c8State(e,'walk');}else c8State(e,'idle');
  }else{if(e.state!=='walk')c8State(e,'walk');e.x+=e.face*22*dt;if(e.x<e.minX||e.x>e.maxX){e.x=clamp(e.x,e.minX,e.maxX);e.face*=-1;}}
 }
}
function updateCastle8Boss(e,dt){
 if(castle8.stage!=='duel')return;
 const dx=hero.x-e.x,dist=Math.abs(dx),same=Math.abs(hero.y-e.y)<55;
 if(e.state==='hit'){if(e.t>.42){c8State(e,'recover');e.cooldown=1.0;}return;}
 if(e.state==='guard'){if(e.t>.78){c8State(e,'recover');e.cooldown=.75;}return;}
 if(e.state==='recover'){if(e.cooldown<=0&&!castle8.fireballs.length)c8State(e,'idle');return;}
 if(e.state==='cast'){
  const i=e.shot,at=1.05+i*1.3;
  if(i<e.sequence.length&&e.charged!==i){e.charged=i;gameSound.play('l8-fire-charge',e.x,e.y,.5);if(e.sequence[i]==='high')c8Speak('get-down',true);else if(e.sequence.length>1)c8Speak('theyre-coming');}
  if(i<e.sequence.length&&e.t>=at){c8Fire(e,e.sequence[i]);e.shot++;}
  if(e.shot>=e.sequence.length&&e.t>=at-.2){c8State(e,'recover');e.cooldown=1.6;e.sequence=null;}return;
 }
 if(e.state==='attack'){
  if(e.t>=.9&&!e.fired){e.fired=true;gameSound.sample('sword_swing',e.x,e.y,.65);if(same&&dist<155&&dx*e.face>-10)c8Melee(e);}
  if(e.t>1.6){c8State(e,'recover');e.cooldown=1.15;}return;
 }
 if(e.state==='retreat'){
  const to=e.retreatTo,dir=Math.sign(to-e.x);e.face=Math.sign(dx)||e.face;e.x=clamp(e.x+dir*105*dt,4130,4840);
  if(dist>=320||Math.abs(e.x-to)<8||e.t>3.6){if(dist>265)c8Cast(e);else{c8State(e,'attack');e.attackCount++;}}return;
 }
 e.face=Math.sign(dx)||e.face;
 if(e.cooldown>0)return;
 if(dist>=300){c8Cast(e);return;}
 if(e.attackCount>0&&e.attackCount%3===0){e.attackCount++;e.retreatTo=hero.x<4480?4830:4140;c8State(e,'retreat');c8Speak('run-forrest');return;}
 if(dist<150){e.attackCount++;c8State(e,'attack');c8BossSay('attack');}
 else{c8State(e,'walk');e.x=clamp(e.x+e.face*66*dt,4130,4840);}
}
function castle8Hazards(dt){
 if(hero.hp<=0||level.done)return;castle8.time+=dt;castle8.princess.t+=dt;
 if(castle8.bossBubble&&(castle8.bossBubble.remaining-=dt)<=0)castle8.bossBubble=null;
 if(castle8.stage==='duel'){
  castle8.duelElapsed+=dt;
  if(!castle8.cues.force&&castle8.duelElapsed>.75){castle8.cues.force=true;c8Speak('force-with-you',true);}
  if(!castle8.cues.help&&castle8.duelElapsed>8){castle8.cues.help=true;c8Speak('help-hero');}
  if(hero.hp<=20&&!castle8.critical){if(c8Speak('not-dying',true)){castle8.critical=true;castle8.lowHealth=true;}}
  else if(hero.hp<=35&&!castle8.lowHealth){if(c8Speak('stay-with-me',true))castle8.lowHealth=true;}
  if(castle8.recoverCue&&castle8.time>castle8.recoverCue){castle8.recoverCue=null;c8Speak('get-back-up');}
 }
 for(const p of castle8.fireballs){
  p.age+=dt;p.life-=dt;const steps=Math.max(1,Math.ceil(Math.abs(p.vx*dt)/7));
  for(let i=0;i<steps&&!p.hit;i++){p.x+=p.vx*dt/steps;if(circleHitsHero(p.x,p.y,p.r)){hurtHero(20,true);p.hit=true;gameSound.play('l8-fire-impact',hero.x,hero.y,.6);}}
  if(p.x<4010||p.x>4970)p.hit=true;
 }
 castle8.fireballs=castle8.fireballs.filter(p=>!p.hit&&p.life>0);
 castle8.particles=castle8.particles.filter(p=>(p.life-=dt)>0);
}

'use strict';
// Recorded voices remain unmodified. Event selection does not force all lines into one run.
let c8VoiceSource=null;
function castle8PauseVoice(){if(c8VoiceSource){try{c8VoiceSource.stop();}catch{}c8VoiceSource=null;}}
function c8Speak(short,urgent=false){
 const v=castle8.voice,id='princess-l8-'+short,clip=C8_VOICES.find(c=>c.id===id);if(!v||!clip||hero.hp<=0)return false;
 if((v.cooldowns[id]||-100)>castle8.time||clip.frequency==='once'&&v.used[id])return false;
 if(v.active&&(!urgent||clip.priority<=v.active.priority))return false;
 if(!urgent&&castle8.time-v.last<5)return false;
 castle8PauseVoice();gameSound.stopDialogue();clearActiveDialogue();dialogue.queue=[];
 v.active={id,duration:clip.duration_seconds,priority:clip.priority};v.elapsed=0;v.last=castle8.time;v.used[id]=true;v.cooldowns[id]=castle8.time+Math.max(clip.cooldown_seconds||0,9);
 // Captions are intentionally not guessed from filenames; use the supplied performance.
 return true;
}
function castle8AudioTick(dt){
 const v=castle8.voice;if(!v)return;if(paused||document.hidden){castle8PauseVoice();return;}
 if(hero.hp<=0){castle8PauseVoice();v.active=null;return;}
 if(!v.active)return;
 if(!gameSound.enabled)castle8PauseVoice();
 if(!c8VoiceSource&&gameSound.ready&&gameSound.enabled){const gain=(C8_VOICE_GAINS[v.active.id]||1.2)*2;c8VoiceSource=gameSound.play(v.active.id,hero.x,hero.y,gain,1,false,true,v.elapsed)||null;}
 v.elapsed+=dt;
 if(v.elapsed>=v.active.duration){castle8PauseVoice();v.active=null;}
}
