 hero.x=4500;hero.y=366;hero.face=-1;hero.vx=hero.vy=0;hero.ground=true;hero.climbing=false;state('idle');clearInput();
 Object.assign(c8Boss(),{hidden:false,x:4190,y:366,state:'idle',t:0,cooldown:1.5,face:1});
 castle8.princess={x:5065,y:307,depthScale:.85,action:'idle',t:0,face:-1};level.checkpoint=true;invulnerable=1.2;c8BossSay('combat_start',true);
