 castle8.fireballs=[];bullets=[];castle8PauseVoice();castle8.voice.active=null;resetDialogues();clearInput();hero.vx=hero.vy=0;hero.y=366;hero.ground=true;hero.climbing=false;hero.face=1;state('idle');gameSound.stopDialogue();updateCastle8HUD();
