function completeCastle8(){castle8.stage='complete';level.done=true;castle8.fireballs=[];clearInput();castle8PauseVoice();castle8.voice.active=null;gameSound.reset();paused=true;document.getElementById('castle8End').hidden=false;persistCastle8();updateCastle8HUD();}
function castle8Busy(dt){
 if(castle8.stage==='complete')return true;
 if(!['arrival','victory'].includes(castle8.stage))return false;
 castle8.sceneTime+=dt;castle8.time+=dt;clock+=dt;if(castle8.bossBubble&&(castle8.bossBubble.remaining-=dt)<=0)castle8.bossBubble=null;hero.t+=dt;const t=castle8.sceneTime,p=castle8.princess;p.t+=dt;
 if(castle8.stage==='arrival'){
  hero.x=castle8.arrivalStart+(4430-castle8.arrivalStart)*clamp(t/3.2,0,1);hero.face=t<8.7?1:-1;state(t<3.2?'walk':'idle');
  if(t<1.1){p.action='standup';p.t=t;p.x=4680;}
  else if(t<4.2){p.action='walk';p.x=4680+(4462-4680)*clamp((t-1.1)/3.1,0,1);}
  else if(t<6.8){p.action='kiss';p.t=t-4.2;p.x=4462;}
  else if(t<8.8){p.action='idle';p.x=4462;}
  else{const q=clamp((t-8.8)/5.4,0,1);p.action=t<14.2?'walk':'idle';p.face=1;p.x=4462+(5065-4462)*q;p.y=366-59*q;p.depthScale=1-.15*q;}
  c8Cue('hello',.4,'welcome-late');c8Cue('sweet',3.0,'welcome-sweet');c8Cue('behind',8.6,'behind-you');c8Cue('corner',12.1,'baby-corner');
  const b=c8Boss();if(t>8.2){b.hidden=false;b.x=4020+170*clamp((t-8.2)/3,0,1);b.state=t<11.2?'walk':'idle';b.t+=dt;}
  if(t>=15)beginCastle8Duel();
 }else{
  hero.x=castle8.winStart+(castle8.winX-castle8.winStart)*clamp(t/1.6,0,1);state(t<1.6?'walk':'idle');hero.face=1;
  if(t<3.9){const q=clamp(t/3.9,0,1);p.action='walk';p.face=-1;p.x=5065+(castle8.winX+32-5065)*q;p.y=307+59*q;p.depthScale=.85+.15*q;}
  else if(t<6.5){p.action='kiss';p.t=t-3.9;p.x=hero.x+32;}
  else if(t<9){p.action='idle';p.face=-1;p.x=hero.x+32;}
  else{hero.x=castle8.winX+(5180-castle8.winX)*clamp((t-9)/5,0,1);state('walk');p.action='walk';p.face=1;p.x=hero.x+47;}
  c8Cue('win',.2,'knew-it');c8Cue('trust',2.0,'never-doubt');c8Cue('joke',6.7,castle8.closeCall?'rescuing-you':'no-place-home');c8Cue('leave',9.2,'leaving-now');
  const b=c8Boss();if(b)b.t+=dt;
  if(t>=14.5)completeCastle8();
 }
 updateCastle8HUD();return true;
}
