'use strict';
function c8Backdrop(vw,vh,scale){
 ctx.fillStyle='#232322';ctx.fillRect(0,0,vw,vh);ctx.save();ctx.scale(scale,scale);ctx.translate(-camera.x,-camera.y);
 ctx.save();ctx.beginPath();ctx.rect(-1000,-1500,5010,2500);ctx.clip();
 const im=castle8Art.gallery,hh=1000,ww=hh*im.width/im.height,offset=camera.x*.70;
 for(let i=-1;i<3;i++)ctx.drawImage(im,offset+i*ww,-574,ww,hh);
 ctx.restore();
 if(camera.x+W>3930){ctx.save();ctx.beginPath();ctx.rect(3930,-1000,1300,2100);ctx.clip();const room=castle8Art.room;ctx.drawImage(room,3930,366-575,1290,1290*room.height/room.width);ctx.restore();}
 // Dust motes remain in world space and never track the actor's movement.
 for(let i=0;i<45;i++){const x=130+i*119+Math.sin(clock*.2+i)*14,y=-350+(i*97%650)+Math.sin(clock*.3+i*2)*10;ctx.fillStyle='rgba(249,222,160,.18)';ctx.fillRect(x,y,1.7,1.7);}
 ctx.restore();
}
