 ctx.fillStyle='#05080b55';ctx.beginPath();ctx.ellipse(x,p.y,24*depthScale,4,0,0,7);ctx.fill();ctx.save();ctx.translate(x,p.y);ctx.scale((p.action==='kiss'?-1:p.face)*depthScale,depthScale);ctx.drawImage(f.img,-f.anchor[0]*s,-f.anchor[1]*s,f.width*s,f.height*s);ctx.restore();
