function dungeonCampaignEntry(){
 const hp=clamp(hero?.hp??100,1,100),entry=dungeonDefaultEntry();
 entry.player.hp=hp;
 entry.confiscated={hp,maxHP:100,sword:campaignLevel===7?dungeonEntry?.confiscated?.sword??true:hasSword,wealth:Number(wealth)||0,armor:Number(armor)||0,gun:!!level.gun,ammo:level.ammo||0};
 if(campaignLevel===7&&dungeonEntry)return dc(dungeonEntry);
 // Selecting a late chapter directly grants its essential sword, as chapters 2–6 do.
 if(!entry.confiscated.sword)entry.confiscated.sword=true;
 return entry;
}
